function dkHash(ix,iy,sd){let h=(Math.imul(ix,374761393)+Math.imul(iy,668265263)+Math.imul(sd,1274126177))|0;h=Math.imul(h^(h>>>13),1274126177);h^=h>>>16;return (h>>>0)/4294967295;}
