    let x0=1e9,x1=-1,y0=1e9,y1=-1;for(let i=0;i<WALK.length;i++)if(WALK[i]){const gx=(i/MCELLS)|0,gy=i%MCELLS;if(gx<x0)x0=gx;if(gx>x1)x1=gx;if(gy<y0)y0=gy;if(gy>y1)y1=gy;}
