  if(village&&curMapId===4100){const wx=gx+33344,wy=gy+32512;if(wx<VPLAZA[0]||wx>VPLAZA[1]||wy<VPLAZA[2]||wy>VPLAZA[3]||wx+wy<VPLAZA[4]||wx+wy>VPLAZA[5])return false;}   // 奇岩村：只能在廣場裡走
