  if(walkable(nx,ny)){o.x=nx;o.y=ny;return true;}
  if(dx&&walkable(nx,o.y)){o.x=nx;return true;}
  if(dy&&walkable(o.x,ny)){o.y=ny;return true;}
  // 等角格子的牆是斜的：沿著格子軸（2:1 斜線）滑行，貼牆時不會被卡住
  const L=Math.hypot(dx,dy);
