  let done=0;setMap(0);const total=list.length+1+(HAVE_ART?9:0);
  const bar=document.getElementById('barfill'),txt=document.getElementById('loadtxt');
  const upd=()=>{bar.style.width=(done/total*100)+'%';txt.textContent=done+' / '+total;};
  const one=(src,store,gf)=>new Promise(res=>{const im=new Image();let fin=false;const end=()=>{if(fin)return;fin=true;done++;upd();res();};im.onload=end;im.onerror=()=>{if(im._fw)return;end();};if(gf)sprLoad(im,gf[0],gf[1]);else im.src=src;store(im);});
  const jobs=[()=>one('assets/ground.png',im=>{imgs.ground=im;})];
