  const f=Math.min(fr,m.frames-1);
  const sx=(f%m.cols)*m.cellW,sy=Math.floor(f/m.cols)*m.cellH;
  if(alpha!==undefined)ctx.globalAlpha=alpha;
  SDI(ctx,im,sx,sy,m.cellW,m.cellH,Math.round(x-m.anchorX),Math.round(y-m.anchorY),m.cellW,m.cellH);
  if(alpha!==undefined)ctx.globalAlpha=1;
