const MG_OFF=new Set([17]);   // 法師升級選項不出現的魔法：極光雷電（跟電弧重複；妖精、王族照常）
const MGNEW=new Set([4,6,7,15,16,17,22,25,29,30,34,38,53,70,74,77]);   // 有新版圖示的魔法（assets/spell/mg_編號.png）
const NEWIC={speed:'c_speed',hp:'c_hp',magnet:'c_magnet',orb:'c_orb',cast:'c_cast',dmg:'c_dmg',rate:'c_rate',range:'c_range'},NEWPASS={151:'c_151',158:'c_158',132:'c_132',149:'c_149',175:'c_175',174:'c_174',166:'c_166',150:'c_150',168:'c_168',164:'c_164'},NEWW=new Set(['sword','tohandsword','dagger','singlespear','spear','staff','tohandstaff','blunt','bow','claw','edoryu','gauntlet','chainsword','kiringku']);   // 新版共通技能圖示（assets/spell/c_*.png、cw_*.png）
function buildPool(){
  const pool=[],ck=window.__ck||'elf',elf=ck==='elf',RW=LU.W_RARE,wt=curWType(),wg=LU.wgroup(wt),bow=wg==='bow';
  // 1. 基本強化：全職業通用
  for(const u of UP_POOL){
    if(!elf&&(u.id==='dmg'||u.id==='range'||u.id==='rate'))continue;   // 妖精弓箭手專用
    if(u.id==='cast'&&!(elf||ck==='mage'||ck==='royal'))continue;   // 施法速度：妖精、法師、王族（會學魔法的職業）都能骰到
    if(BOWONLY.has(u.id)&&!bow)continue;
    if((P.ups[u.id]||0)<u.max)pool.push({key:u.id,name:u.name,desc:typeof u.desc==='function'?u.desc((P.ups[u.id]||0)+1):u.desc,have:P.ups[u.id]||0,tag:'基本強化',fx:u.fx,wt:RW.basic,sid:NEWIC[u.id],icon:({orb:'u_orb',hp:42,dmg:'u_dmg',rate:'u_rate',cast:'u_cast',speed:'u_speed',magnet:'u_magnet',range:'u_range'})[u.id]});
  }
  for(const u of PASS){if(!LU.GEN_PASS.includes(u.id))continue;const h=rk(u.id);if(h<u.max)pool.push({key:'p'+u.id,name:u.name,desc:u.d(h+1),have:h,icon:u.id,sid:NEWPASS[u.id],tag:'基本強化',fx:u.fx||(()=>{recalc();}),wt:RW.basic});}
  {const m=LU.MPR,h=P.ups.g_mpr||0;if(h<m.max)pool.push({key:'g_mpr',name:m.name,desc:m.desc(h+1),have:h,icon:'u_mpr',sid:'c_mpr',tag:'基本強化',fx:()=>{recalc();},wt:RW.basic});}
  // 2. 武器專屬強化：只看目前裝備的武器（妖精的弓強化已在上面）
  if(wg&&LU.WENH[wg]&&!(elf&&bow)){const c=LU.WENH[wg],h=P.ups['w_'+wg]||0;if(h<c.max)pool.push({key:'w_'+wg,name:c.name,desc:LU.wdesc(wg,h+1),have:h,tag:'武器強化',sid:NEWW.has(wg)?'cw_'+wg:undefined,wsrc:NEWW.has(wg)?undefined:(()=>{const w=weaponIt();return w?'assets/icons/'+w.id+'.png':'';})(),fx:()=>{},wt:RW.weapon});}
  // 3. 職業被動／主動技能（妖精沿用原本的；其他職業的技能池第二階段起加入）
  if(elf||ck==='mage'||ck==='royal'){   // 王族：戰局內也能學魔法，但最高只到 3 級魔法
    if(elf)for(const u of PASS){if(LU.GEN_PASS.includes(u.id)||(BOWONLY.has(u.id)&&!bow))continue;const h=rk(u.id);if(h<u.max)pool.push({key:'p'+u.id,name:u.name,desc:u.d(h+1),have:h,icon:u.id,sid:NEWPASS[u.id],tag:'職業被動技能',fx:u.fx||(()=>{recalc();}),wt:RW.passive});}
    for(const id in MAGIC){const k=MAGIC[id],h=P.ups['m'+id]||0;if(ck==='mage'&&MG_OFF.has(+id))continue;if(k.tier>(elf?6:ck==='royal'?3:10)||h>=5||(elf?level<k.tier*1.2-1:false))continue;   // 法師同原版：N 級魔法要 Lv4×N 才學得到（已學過的可繼續升級）
        // 精靈只能學到 6 級魔法（同原版）
      if(k.undead||k.slow){pool.push({key:'m'+id,name:k.name,desc:k.undead?'自動施放，範圍內不死系怪物有機率即死（王除外，等級越高機率越高），每 '+magicCd(k,h+1).toFixed(1)+' 秒':'自動施放，範圍內怪物移動速度減半 '+slowSec(h+1)+' 秒，每 '+magicCd(k,h+1).toFixed(1)+' 秒',have:h,icon:k.id,sid:MGNEW.has(+id)?'mg_'+id:undefined,tag:'職業主動技能',fx:()=>{},wt:RW.active});continue;}
      pool.push({key:'m'+id,name:k.name,desc:k.id===74?'自動施放，在目標周圍連續落 '+METN+' 顆，每顆傷害 '+Math.round((k.dv+k.dc*(k.dd+1)/2)*DMGSCALE*0.8*magicDmgMul(h+1)*METF)+'，每 '+magicCd(k,h+1).toFixed(1)+' 秒':'自動施放，傷害 '+Math.round((k.dv+k.dc*(k.dd+1)/2)*DMGSCALE*0.8*magicDmgMul(h+1)*magicBoost(k))+(k.area?'（範圍'+(k.id===74&&isMage()?'＋'+Math.round(MET_R[Math.min(4,h)]*100)+'%，一次落 '+magicShots(k,h+1)+' 顆':'')+'）':magicShots(k,h+1)>1?'，一次 '+magicShots(k,h+1)+' 發':'')+'，每 '+magicCd(k,h+1).toFixed(1)+' 秒',have:h,icon:k.id,sid:MGNEW.has(+id)?'mg_'+id:undefined,tag:'職業主動技能',fx:()=>{},wt:RW.active});}
  }
  if(ck==='royal'){for(const u of ROYAL_UP){const h=P.ups[u.key]||0;if(h<u.max)pool.push({key:u.key,name:u.name,desc:u.d(h+1),have:h,tag:u.tag,sid:u.key,fx:()=>{},wt:u.tag==='職業主動技能'?RW.active:RW.passive});}}
  if(CK_UP[ck]){for(const u of CK_UP[ck]){if(u.hid)continue;const h=P.ups[u.key]||0;if(h<u.max)pool.push({key:u.key,name:u.name,desc:u.d(h+1),have:h,tag:u.tag,sid:u.sid,fx:()=>{},wt:u.tag==='職業主動技能'?RW.active:RW.passive});}}
  // 4. 變身
  const fl=formEligible();
  if(fl.length&&level>=3){const by={};for(const d of fl)(by[formTier(d)]||(by[formTier(d)]=[])).push(d);   // 每個顏色各抽 1 隻變身放進候選，顏色機率跟技能一樣
    for(const tk in by){const d=by[tk][Math.floor(Math.random()*by[tk].length)];
    pool.push({key:'f'+d.id,tier:tk,name:'變身：'+d.name,desc:'外觀換成'+d.name+'；'+formDescOf(d)+(P.form?'（換掉目前的變身）':''),have:0,tag:({white:'一般變身',green:'高級變身',blue:'稀有變身',red:'英雄變身',purple:'傳說變身',gold:'神話變身',cyan:'唯一變身'})[tk]||'變身',form:d,wt:RW.form,fx:p=>{p.form=d;recalc();addChat('變身成「'+d.name+'」！','sys');}});}}
  return pool;
}
