// ---- 活動專區：無限刷怪區（每次最多 2 小時；限時活動開放進入 3 小時）。數字都在這一個表，要調整只改這裡 ----
// m＝已經過幾分鐘（0~60）。出怪速度、怪物強度、掉寶倍率都隨 m 線性上升；怪物種類由低等到高等逐步解鎖，第 40 分鐘起全部種類都會出現。
const evD=m=>m<=60?m:60+(m-60)/3;   // 第 60 分鐘之後難度成長減慢到 1/3（總共 180 分鐘）：血量／傷害／出怪速度／掉寶都吃這個「難度分鐘」
const EVZ={
  len:7200,
  rate:m=>3+0.1*evD(m),                       // 每秒出怪數：第 0 分 3/秒（180/分）→ 第 60 分 9/秒（540/分）；同時存活仍受場上上限限制
  hp:m=>2.5+0.3*Math.floor(evD(m)),           // 新出怪物血量倍率：玩家是滿裝來打的，一開始就是一般戰局封頂的 ×2.5，之後每分鐘再 +30%：第 60 分 ×20.5
  dmg:m=>2.5+0.3*Math.floor(evD(m)),          // 新出怪物傷害倍率：同上，一開始 ×2.5，每分鐘 +30%：第 60 分 ×20.5
  spd:m=>1+0.004*evD(m),                      // 移動速度：第 60 分 +24%
  elite:m=>0.06+0.0025*evD(m),                // 菁英怪機率：6% → 21%
  drop:m=>1+0.02*Math.floor(evD(m)),          // 掉寶倍率（裝備、卷軸、道具、寶箱都乘）：從一般戰局的 ×1 開始，每分鐘 +0.02，第 60 分 ×2.2
  unlock:m=>Math.min(1,0.5+m/30*0.5)     // 解鎖的怪物比例（依等級由低到高）：第 0 分 50% → 第 30 分 100%
};
let _evPool=null;
function evPool(){if(!_evPool){const seen=new Set();_evPool=XALL.filter(d=>!d.boss&&!d.hpl&&!d.next&&d.acts&&d.acts.walk&&d.acts.attack&&d.acts.death&&d.hp>0&&!seen.has(d.id)&&seen.add(d.id)).sort((a,b)=>a.lvl-b.lvl||a.id-b.id);}return _evPool;}
