  const dr=ckLv('d_double');if(dr)v*=1+CKV.double.ch[dr-1]*CKV.double.mul[dr-1];
  const sr=ckLv('l_slay');if(sr)v*=1+(CKV.slay.seg[sr-1]-1)*CKV.slay.mul[sr-1];
