// 目前所有技能的秒傷加總（理論值）：普攻＋魔法＋職業主動技能＋弓的特殊被動＋皇家召喚物。固定公式、不隨機，所以畫面上不會跳
function dpsTotal(noSum){try{
  let t=dpsBasic();
  const wr=wm().rate;
  for(const key of ['shield','spin']){const kk={shield:'k_shield',spin:'l_spin'}[key],r=ckLv(kk),tb=CKV[key];if(r&&tb&&tb.mul){const cd=Array.isArray(tb.cd)?tb.cd[r-1]:tb.cd;if(cd>0)t+=shotAvg(tb.mul[r-1],true)/(cd/wr);}}
  for(const k in P.ups){if(!/^m\d+$/.test(k)||!P.ups[k])continue;const id=+k.slice(1),m=MAGIC[id];if(!m||m.undead||m.slow)continue;const r=P.ups[k];
    let v=(m.dv+m.dc*(m.dd+1)/2+P.orig.magicDmg)*DMGSCALE*0.8*magicDmgMul(r)*magicBoost(m)*(1+0.06*upg.int)*PL.skill()*formSkill()*STAT.intCoef(P.st.int,P.st.sp)*((stfW()||{dmg:1}).dmg)*TM.dmg*TM.skill;
    if(m.tier<=6&&P.orig.magicCrit)v*=1+0.5*P.orig.magicCrit/100;
    t+=v*magicShots(m,r)/magicCd(m,r);}
  const ar=rk(174);if(ar>0&&isBow())t+=3*shotAvg(2.8,true)/accCd(ar);
  const bn=rk(175);if(bn>0)t+=burnDps(bn);
  if(!noSum&&(window.__ck==='royal'||formAb().wolves)&&!village){const w=sumWant(),rate=1.8*(1+0.15*RUP('r_order')),crit=0.08*RUP('r_aim'),multi=1+RUP('r_morale');
    for(const ty in w){if(!w[ty])continue;const s=sumStats(ty),S=SD_OF(ty);if(!S||!S.acts)continue;
      const act=prep(S.acts.attack),per=act.total*TICK/1000/rate+0.12;let d=s.dmg*(1+crit);if(ty==='shark')d*=1.3;
      t+=w[ty]*d*(ty==='archer'?Math.min(3,1+Math.floor(RUP('r_morale')/2))+(mercF('archer')?mercF('archer').arrows:0):1)*(mercF(ty)?1+mercF(ty).aspd:1)/per;}}
  return Math.max(0,t);}catch(e){return 0;}}
function dpsNow(){try{return dpsBasic();}catch(e){return 0;}}
