function useScrollOn(sc,tg){
  const sd=idef(sc),td=idef(tg);
  const isW=/Weapon/.test(sd.cls),isA=/Armor/.test(sd.cls);
  if(isW&&td.kind!=='weapon'){addChat('這張卷軸只能對武器使用。','warn');return false;}
  if(isA&&td.kind!=='armor'){addChat('這張卷軸只能對防具使用。','warn');return false;}
  if(td.kind!=='weapon'&&td.kind!=='armor'){addChat('這個道具無法強化。','warn');return false;}
  const blessed=sc.id>=140000,safe=Math.max(0,td.safe<0?0:td.safe);
  if((tg.ench||0)>=ENCH_MAX_B){addChat('已經是最高的 +'+ENCH_MAX_B+' 了。','warn');return false;}
  if(!blessed&&(tg.ench||0)>=ENCH_MAX){addChat('一般卷軸最高只能強化到 +'+ENCH_MAX+'，要用祝福的卷軸才有機會衝 +'+ENCH_MAX_B+'。','warn');return false;}
  if(false && SRV()){const tsel={id:tg.id,ench:tg.ench||0,eq:tg.eq||''};
    srvDo('enchant',{scroll:sc.id,tgt:tsel},r=>{
      if(r.ok){addChat('你的 '+td.name+(isW?' 發出了銀色的光芒（+':' 發出了金色的光芒（+')+r.ench+'）','sys');pop(P.x,P.y-90,'+'+r.ench+' '+td.name,'#9fe0ff',1.6);}
      else{addChat('你的 '+td.name+' 承受不住強化的力量，化為灰燼了。','warn');pop(P.x,P.y-90,'強化失敗','#ff8a6a',1.6);}
      recalc();invDirty=true;});
    return true;}
  takeItem(sc.id,1);
  let ok,add=1;
  if(!ONLINE&&GM_SURE.has(sc.id)){ok=true;}   // 【測試用，測完刪除】金色必成功卷軸：不管幾 +，一律 +1 成功
  else if(tg.ench<safe){ok=true;if(blessed)add=rndi(1,3);add=Math.max(1,Math.min(add,ENCH_MAX-tg.ench));}
  else{const ch=enchRate(td.kind,tg.ench,safe,blessed);ok=Math.random()<ch;}
  if(ok){
    tg.ench+=add;
    addChat((isW?'你的 ':'你的 ')+td.name+(isW?' 發出了銀色的光芒（+':' 發出了金色的光芒（+')+tg.ench+'）','sys');
    pop(P.x,P.y-90,'+'+tg.ench+' '+td.name,'#9fe0ff',1.6);
  }else{
    const was=iname(tg);
    inv.splice(inv.indexOf(tg),1);
    addChat('你的 '+was+' 承受不住強化的力量，化為灰燼了。','warn');
    pop(P.x,P.y-90,'強化失敗','#ff8a6a',1.6);
  }
  recalc();invDirty=true;srvAct('enchant',{ok:ok?1:0});return true;
}
