function castSkill(id){
  if(!P||!running||paused||over||winsOpen())return;
  const k=SKILLS[id];if(!k||!IMPL[id])return;
  if(!P.known[id])return;
  if((P.cd[id]||0)>0)return;
  if(P.mp<mpCost(k)){addChat('護盾不足。','warn');return;}
  if(k.item&&countItem(k.item)<k.itemN){addChat('材料不足：需要 '+(ITEMS[k.item]?ITEMS[k.item].name:'材料')+' ×'+k.itemN,'warn');return;}
  const t=IMPL[id];
  if(t==='triple'||t==='acc'){
    const tg=nearest(P.range+30);if(!tg){return;}
    if(!useArrow())return;
    const base=Math.atan2((tg.y-18)-(P.y-18),tg.x-P.x);
    const angs=t==='triple'?[base-0.1,base,base+0.1]:[base];
    for(const a of angs)arrows.push({x:P.x,y:P.y-22,vx:Math.cos(a)*600,vy:Math.sin(a)*600,a,life:P.range/600,pierce:t==='acc'?P.pierce+3:P.pierce,hit:new Set(),mul:t==='acc'?2.8:1,sure:t==='acc'});
    P.dir=dirFromVec(Math.cos(base),Math.sin(base));P.shooting=true;P.shootT=0;
  }else if(t==='heal'){spawnFx(FXG[id],P.x,P.y,true);
    const h=((k.dv||10)+rndi(1,k.dd||12))*3;P.hp=Math.min(P.maxhp,P.hp+h);pop(P.x,P.y-70,'+'+Math.round(h),'#7dff9a',1.0);
  }else{
    P.buffs[id]=Math.min(k.dur||960,3600);recalc();if(FXG[id])spawnFx(FXG[id],P.x,P.y,true);
  }
  P.mp-=mpCost(k);if(k.item){takeItem(k.item,k.itemN);srvUse(k.item,k.itemN);}
  P.cd[id]=skillCd(id);
  pop(P.x,P.y-70,k.name,'#9fe0ff',1.0);
}
