  const lx=Math.max(-260,Math.min(260,_pv.x*Z.tele)),ly=Math.max(-160,Math.min(160,_pv.y*Z.tele));   // 預判落點 = 現在位置 + 速度 × 預警秒數
  const nP=Math.ceil(n/2),nN=Math.floor(n/4);
