  lootLog.push({text:name+(n>1?' ×'+n:''),t:0});if(id!==40743&&!(TOUCHDEV&&id===40308))addChat('獲得 '+name+(n>1?' ('+n.toLocaleString()+')':''),'loot');   // 手機：撿到金幣不進訊息欄（頭上的「+累計金幣」飄字就夠了）invDirty=true;
  if(OPT.lootpop&&id!==40308)pop(P.x,P.y-50,name,g.col,1.2);
