const GOLDIMG=new Image();GOLDIMG.src='data:image/png;base64,';   // 金幣地上圖＝最原本的原版圖（GFX 7，31×27，保留黑框、去掉外圈白框），直接內嵌
const GRDC={};function groundImg(id){const k=window.GRD&&GRD[id];if(!k)return null;let im=GRDC[k];if(!im){im=new Image();im.src='assets/ground/'+k+'.png';GRDC[k]=im;}return im;}
const ICONC={};function iconImg(id){let im=ICONC[id];if(!im){im=new Image();im.onerror=()=>{if(!im._assetFallback){im._assetFallback=true;im.src='assets/icons/missing-item.svg';}};im.src='assets/icons/'+id+'.png';ICONC[id]=im;}return im;}
const MATK={40513:1/3,40499:6.75,40519:12,40507:12,40506:9,88:7.5,40515:7.5,40496:6.75,40494:2.7};   // 妖精森林製作材料掉落倍率（和伺服器 econ.js 的 MATK 一致）：初階（蘑菇汁／鬃毛／樹枝／水果）每場約 3~6 個、中階（粗糙米索莉塊／潘的角／元素石）約 2~3 個、純粹米索莉塊約 0.6 個（以一場 400 隻怪估算）
