function goldStageMul(i){i=i|0;return i<=0?0.85:Math.max(0.25,0.5-(i-1)*0.04);}
function rollDrops(m){
  const _dk=dropK();
  if(m.boss){giveLoot('',49099,1,m,'#ffd75e');if(Math.random()<0.05)giveLoot('',40418,1,m,'#c37bff');}   // 首領必掉首領寶箱，5% 再掉特殊寶箱
  else if(m.elite&&Math.random()<0.008*_dk*(m.eAff?m.eAff.length:1))giveLoot('',41244,1,m,'#5aa9ff');                              // 菁英怪 0.8% 掉稀有寶箱
  else if(Math.random()<0.005*_dk)giveLoot('',40737,1,m,'#ffffff');                                       // 普通怪 0.5% 掉普通寶箱
  if(m.boss&&Math.random()<PANA_BOSS_CH){const pid=Object.keys(PANA)[rndi(0,5)];giveLoot(ITEMS[pid].name,+pid,1,m,'#9fd8ff');}   // 萬能藥：高價品，只有王會掉（機率為暫定值）
  if(DOLL_ON&&m.boss&&Math.random()<0.7){const n=rndi(1,2);dollTok+=n;if(RUNON)RUNREP.dt+=n;saveVill();addChat('獲得 魔法娃娃召喚符 ×'+n,'loot');lootLog.push({text:'魔法娃娃召喚符 ×'+n,t:0});}
  if(DOLL_ON&&m.boss&&Math.random()<0.4&&typeof DOLLS!=='undefined'){const left=DOLLS.filter(d=>!ownDolls.includes(d.id));if(left.length){const d=left[Math.floor(Math.random()*left.length)];ownDolls.push(d.id);if(RUNON)RUNREP.dolls.push(String(d.id));saveVill();addChat('王掉落了「'+d.name+'」！已收進魔法娃娃卡冊','loot');lootLog.push({text:d.name,t:0});pop(m.x,m.y-50,d.name,'#ffe27a',2.4);}}
  if(m.def&&m.def.hpl){   // 敵對玩家首領：0.004% 掉該職業可用的 +1~6 武器、另外 0.004% 掉 +1~4 防具
    const pool=k=>{const ci=CKEYS.indexOf(m.def.hcls),r=[];for(const id in ITEMS){const d=ITEMS[id];if(!d||d.kind!==k||NO_DROP.has(+id)||!d.name)continue;if(m.def.hcls==='elf'){if(!d.elf)continue;}else{const u=ITEMUSE[d.id];if(!u||u[ci]!=='1')continue;}r.push(+id);}return r;};
    for(const [k,mx] of [['weapon',6],['armor',4]]){if(Math.random()<HPL_EQ_CH){const p=pool(k);if(p.length){const id=p[Math.floor(Math.random()*p.length)],en=rndi(1,mx),nm='+'+en+' '+ITEMS[id].name;
      const a=Math.random()*6.283,r=rnd(6,26);gitems.push({x:m.x+Math.cos(a)*r,y:m.y+Math.sin(a)*r*0.5,id,n:1,ench:en,name:nm,col:'#ff9bff',t:0,ph:Math.random()*6,keep:true});
      addChat('敵對玩家掉落了「'+nm+'」！','loot');pop(m.x,m.y-30,nm,'#ff9bff',2.4);}}}
  }
  const _m2=false;   // 掉落完全照原廠資料庫（chance 是百萬分率）
  const _dl=m.def.id===45008?m.def.drops.filter(d=>d.item!==1):m.def.id===45009?m.def.drops.concat([{item:1,name:'歐西斯匕首',min:1,max:1,chance:10000}]):m.def.drops;   // 歐西斯匕首照原版：妖魔才掉、哥布林不掉，機率再壓低
  for(const d of _dl){
    if(NO_DROP.has(d.item))continue;
    const _nm=(ITEMS[d.item]&&ITEMS[d.item].name)||d.name||'';if(_m2&&/精靈玉/.test(_nm))continue;
    const _k=ITEMS[d.item]&&ITEMS[d.item].kind,ch=d.chance/1000000*DROP_MULT*_dk*(MATK[d.item]||1)*((_k==='weapon'||_k==='armor')?EQ_MULT:(d.item===40308?GOLD_MULT*goldStageMul(stageIdx):(/卷軸/.test((ITEMS[d.item]&&ITEMS[d.item].name)||d.name||'')?SCR_MULT:ETC_MULT)));
    if(Math.random()<ch){
      let n=d.min+Math.floor(Math.random()*(d.max-d.min+1));
      if(d.item===40308&&STAGES[stageIdx]&&STAGES[stageIdx].cash)n*=CASHZ.gold;   // 刷錢專區：金幣 +100%
      giveLoot(d.name||('道具#'+d.item),d.item,n,m);
    }
  }
}
