// 2026-11-14 經驗重新設計（爽度：越往後打越多，不會因為下一關怪物等級低而變少）
//   路線深度 pos：同一條路線的第幾關（0 開始）；無限刷怪區每 6 分鐘算一關（最多 10）
//   保底等級：怪物等級低於「8 ＋ 4×pos」時，經驗照保底等級算（例如古魯丁地監 1F、騎士洞窟 1F 的低等怪不會讓經驗掉下來）
//   深度加成：每往後一關 +25%；首領：(40 ＋ 等級×2) × 深度加成（以前固定 60）
function routePos(){const ST=STAGES[stageIdx];if(!ST)return 0;if(ST.endless)return Math.min(10,Math.floor((stageT||0)/360));let i=stageIdx,n=0;while(i>0&&!STAGES[i-1].last){i--;n++;}return n;}
function xpGem(m){const pos=routePos(),lv=Math.max(m.def.lvl||1,8+4*pos),mul=1+0.25*pos;return m.boss?Math.round((40+lv*2)*mul):Math.max(1,Math.round((1+lv*0.3)*mul));}
function xpNeedOf(l){return Math.max(9,Math.round(2.479+4.8955*l+0.8097*l*l-0.027986*l*l*l+0.000562*l*l*l*l));}   // 2026-11-14 平滑曲線：從原本「每 10 級跳一階」的樓梯中間穿過，總量跟原本差不多，但每一級都平順往上
function giveXp(v){
  if(level>=100){xp=0;return;}
  xp+=v*P.dx.expMul*TM.exp;
  while(level<100&&xp>=xpNeed){xp-=xpNeed;level++;xpNeed=xpNeedOf(level);addChat('戰局等級提升！Lv.'+level,'sys');spawnFx(2127,P.x,P.y,true,0,0.07);SND.play(517,0.9,300);openLevelUp();}
}
