function formPreview(d){
  const N=128,cv=document.createElement('canvas');cv.width=N;cv.height=N;cv.className='fpv';cv.style.cssText='width:48px;height:48px';
  const x=cv.getContext('2d'),a=d.acts.walk||d.acts.idle;
  let seen=false;
  const tick=()=>{
    if(cv.isConnected)seen=true;else if(seen){clearInterval(iv);return;}else return;
    x.clearRect(0,0,N,N);x.imageSmoothingEnabled=false;
    const s=frameOf(a,performance.now(),true),fr=s[1];let file=s[0]+5;for(const dd of [5,4,6,3,7,2,0,1])if(META[d.gfx]&&META[d.gfx][s[0]+dd]){file=s[0]+dd;break;}
    const m0=META[d.gfx]&&META[d.gfx][file],im0=m0&&needImg(d.gfx,file);
    let bb=null;if(m0&&im0&&im0.naturalWidth)bb=fpMeasure(d.gfx,file,im0,m0);
    if(!bb&&m0)bb=FORMBB[d.gfx]||[-m0.anchorX,-m0.anchorY,m0.cellW-m0.anchorX,m0.cellH-m0.anchorY];
    for(const g of [d.shadow,d.gfx]){
      if(!g)continue;const m=META[g]&&META[g][file],im=needImg(g,file);if(!m||!im||!im.naturalWidth)continue;
      const f=Math.min(fr,m.frames-1),sx=(f%m.cols)*m.cellW,sy=Math.floor(f/m.cols)*m.cellH;
      let K=1,ox=N/2,oy=N/2;
      if(bb){K=Math.min(5,(N-6)/Math.max(bb[2]-bb[0],bb[3]-bb[1],1));ox=N/2-(bb[0]+bb[2])/2*K;oy=N/2-(bb[1]+bb[3])/2*K;}   // 依實際畫到的範圍置中、放大到佔滿格子
      if(g===d.shadow)x.globalAlpha=0.38;
      SDI(x,im,sx,sy,m.cellW,m.cellH,Math.round(ox-m.anchorX*K),Math.round(oy-m.anchorY*K),Math.round(m.cellW*K),Math.round(m.cellH*K));
      x.globalAlpha=1;
    }
  };
  const iv=setInterval(tick,90);tick();return cv;
}
function placeLv(){const t=document.getElementById('timeT'),d=document.getElementById('lvdlg');if(!t||!d)return;const r=t.getBoundingClientRect();if(r.width){d.style.left=(r.left+r.width/2)+'px';d.style.bottom=Math.max(8,innerHeight-r.top+6)+'px';}}   // 圖示放在戰局時間正上方
