  updateBursts(dt);updateArcs(dt);meteorTick(dt);chestQueueTick();
  if(village){P.hp=Math.min(P.maxhp,P.hp+P.maxhp*0.2*dt);P.mp=Math.min(P.maxmp,P.mp+P.maxmp*0.2*dt);netTick(dt);}
  // 玩家
  let mx=0,my=0;
  if(keys['a']||keys['arrowleft'])mx--;if(keys['d']||keys['arrowright'])mx++;
  if(keys['w']||keys['arrowup'])my--;if(keys['s']||keys['arrowdown'])my++;
  if(JOY.on){mx=JOY.x;my=JOY.y;}   // 手機虛擬搖桿
  if(village&&npcOpen){mx=0;my=0;P.dest=null;P.talkNpc=null;}   // 村莊對話中：畫面照常跑，只是人物原地站著
  if(mx||my){P.dest=null;P.talkNpc=null;}
  else if(MOUSE.held&&!uiBlock()&&!paused){const w=mouseWorld();P.dest={x:w.x,y:w.y};P.talkNpc=null;}
