  P.invul=Math.max(0,P.invul-dt);if(P.curseT>0)P.curseT-=dt;if(P.frzT>0)P.frzT-=dt;else if(P.frzN)P.frzN=null;eTick(dt);
  P.mp=Math.min(P.maxmp,P.mp+P.mpRegen*dt);P.skCd=Math.max(0,P.skCd-dt);P.potCd=Math.max(0,(P.potCd||0)-dt);
  if(P.hpRegen){const b4=P.hp;P.hp=Math.min(P.maxhp,P.hp+P.hpRegen*dt);P._rg=(P._rg||0)+(P.hp-b4);P._rgT=(P._rgT||0)+dt;if(P._rg>=1&&P._rgT>=1.2){pop(P.x,P.y-60,'+'+Math.floor(P._rg),'#7dff9a',0.9);P._rg-=Math.floor(P._rg);P._rgT=0;}}
  for(const k in P.cd)if(P.cd[k]>0)P.cd[k]=Math.max(0,P.cd[k]-dt);
