    if(m.boss&&!m.enr&&m.hp>0&&m.hp<=m.maxhp/3){m.enr=1;m.dmgK*=1.6;m.slT=1.5;pop(m.x,m.y-80,'狂暴！','#ff3b30',1.6);}   // 首領剩 1/3 血：傷害 +60%、攻擊動作與冷卻快 50%、施放技能機率 +50%
