    if(m.fcd>0)m.fcd-=dt;m.stT+=dt*1000*(m.state==='attack'?ek:1);m.hurtT=Math.max(0,m.hurtT-dt);m.cd-=dt*ek;if(m._hp!==undefined&&m.hp<m._hp-0.01&&m.hp>0){SND.mon(m,'damage');{const H=HIDER[m.def.id];if(H&&!m.boss&&m.state!=='hide'&&m.state!=='rise'&&m.def.acts[H.hide]&&m.hp<m.maxhp/3&&Math.random()<0.2){m.state='hide';m.actK=H.hide;m.stT=0;m.hitDone=true;m.spl=null;SND.mon(m,H.hide);}}}m._hp=m.hp;if(m.slowT>0)m.slowT-=dt;
    if(m.burn>0){m.burn-=dt;m.burnAcc=(m.burnAcc||0)+dt;if(m.burnAcc>=1){m.burnAcc-=1;const bd=m.burnD*rnd(0.9,1.1);m.hp-=bd;pop(m.x+rnd(-8,8),m.y-44,String(Math.round(bd)),'#ff3b30',0.8);if(m.hp<=0){killMon(m);continue;}}}
