  if(village||over||SCR_REV||!inv.some(i=>i.id===40089&&i.n>0))return false;   // 復活卷軸：每一場戰局只能用一次
  SCR_REV=1;takeItem(40089,1);srvUse(40089,1);saveSave();invDirty=true;P.hp=Math.max(1,Math.round(P.maxhp*0.5));P.invul=3;P.hurt=0;
