function ckHoly(){const r=ckLv('m_holy');if(!r)return false;const S=ckState();if(S.holyT>time)return true;if(S.cd.holy>0)return false;S.holyT=time+HOLY.sec[r-1];S.cd.holy=HOLY.cd;pop(P.x,P.y-74,'聖結界','#fff3a0',0.9);spawnFx(CKFX.holy,P.x,P.y,true);return true;}
function ckRed(){let r=0;const a=ckLv('k_guard'),b=ckLv('l_skin');if(a)r+=CKV.guard.red[a-1];if(b)r+=CKV.skin.red[b-1];const S=P.sks;if(S&&S.dash&&S.dash.t<S.dash.dur)r+=S.dash.red;return Math.min(CKV.red_cap,r);}
function ckDmg(m,mul){const dm=shotRoll(m,mul,true,true);if(dm<=0||m.dead)return 0;m.hp-=dm;m.hurtT=0.12;ckLeech(dm);if(OPT.dmg)pop(m.x,m.y-44,String(Math.round(dm)),'#ffb347',0.6);if(m.hp<=0)killMon(m);return dm;}
function ckCtl(m,ux,uy,dist,stun){   // 擊退／暈眩：普通怪全效、菁英減半、首領免疫；同一隻怪 1 秒內只吃一次
  if(m.dead||m.boss||(m.ctlAt!==undefined&&time-m.ctlAt<CKV.ctl_gap))return;
  const k=m.elite?0.5:1;m.ctlAt=time;
  if(dist>0){m.kbT=CKV.shield.kbT;m.kbx=ux*dist*k/CKV.shield.kbT;m.kby=uy*dist*k/CKV.shield.kbT;}
  if(stun>0){m.stunT=Math.max(m.stunT||0,stun*k);m.cd=Math.max(m.cd||0,stun*k);}
}
function ckDodge(){const r=ckLv('d_dodge');if(!r)return false;const S=ckState();if(S.cd.dodge>0)return false;if(Math.random()<CKV.dodge.ch[r-1]){S.cd.dodge=CKV.dodge.icd;pop(P.x,P.y-60,'閃避','#9fe8ff',0.8);spawnFx(CKFX.dodge,P.x,P.y,true);return true;}return false;}
function ckNear(ex,x,y){let b=null,bd=520;for(const m of mons){if(m.dead||m===ex||m.hid)continue;const d=Math.hypot(m.x-x,m.y-y);if(d<bd){bd=d;b=m;}}return b;}
function ckHit(m,amt){if(!m||m.dead||!(amt>0))return;if(m.boss&&ckSlayOn())amt*=1+CKV.slayer.up;m.hp-=amt;m.hurtT=0.12;if(OPT.dmg)pop(m.x,m.y-44,String(Math.round(amt)),'#ffb347',0.6);if(m.hp<=0)killMon(m);}
function ckCounter(att,dIn){   // 反擊屏障：被打到時啟動；啟動期間每次被攻擊都反擊（被打的傷害＋玩家傷害×倍率）
  const r=ckLv('k_counter');if(!r||!att||att.dead)return;const S=ckState();
  if(!(S.cntT>time)){if(S.cd.cnt>0)return;S.cntT=time+CKV.counter.dur[r-1];S.cd.cnt=CKV.counter.cd;S.cntFx=0;pop(P.x,P.y-74,'反擊屏障','#ffd27a',0.9);}
  const add=shotAvg(CKV.counter.mul[r-1],true);
  hitFx(CKFX.counter,att.x,att.y,false);ckHit(att,(dIn||0)+add);
  const R=CKV.counter.rad*GRID;for(const m of mons){if(m.dead||m===att)continue;if(Math.hypot(m.x-P.x,m.y-P.y)<=R+(m.boss?18:0))ckHit(m,add);}
}
