function ckClone(a,mul){return {x:P.x,y:P.y-22,vx:a.vx,vy:a.vy,a:a.a,life:a.life,pierce:a.pierce,hit:new Set(),melee:a.melee,mul:mul,extra:true};}
function ckAfterAttack(a){   // 普通攻擊打出去之後：雙重破壞／屠宰者的追加攻擊（追加的不再觸發任何追加）
  if(!a||a.extra)return;const S=ckState();
  const dr=ckLv('d_double');if(dr&&Math.random()<CKV.double.ch[dr-1])S.q.push({t:CKV.double.gap,dbl:1,a:ckClone(a,CKV.double.mul[dr-1])});
  const sr=ckLv('l_slay');if(sr&&a.melee)for(let i=1;i<CKV.slay.seg[sr-1];i++)S.q.push({t:CKV.slay.gap*i,sl:i===1,a:ckClone(a,CKV.slay.mul[sr-1])});
}
function ckTick(dt){
  if(village||!P||!(dt>0)||P.hp<=0)return;const S=ckState();
  {const wr=wm().rate*(1+TM.cdr);for(const k in S.cd)if(S.cd[k]>0)S.cd[k]-=dt*wr;}   // 武器的攻擊速度強化（疾刃／連擊／拳擊）也讓職業技能冷卻變快
  // 追加攻擊佇列
  for(let i=S.q.length-1;i>=0;i--){const q=S.q[i];q.t-=dt;if(q.t<=0){q.a.x=P.x;q.a.y=P.y-22;arrows.push(q.a);if(q.dbl)spawnFx(CKFX.double,P.x,P.y,true);if(q.sl)spawnFx(CKFX.slay,P.x,P.y,true);S.q.splice(i,1);}}
  // 移動方向（平滑）
  const vx=(P.x-S.px)/dt,vy=(P.y-S.py)/dt;S.px=P.x;S.py=P.y;const sp=Math.hypot(vx,vy);
  if(sp>25){const k=Math.min(1,dt*10);S.mx=(S.mx||0)+((vx/sp)-(S.mx||0))*k;S.my=(S.my||0)+((vy/sp)-(S.my||0))*k;const l=Math.hypot(S.mx,S.my)||1;S.fx=S.mx/l;S.fy=S.my/l;S.moving=true;}
  else{S.moving=false;if(!S.set){const a=(P.dir*45-135)*Math.PI/180;S.fx=Math.cos(a);S.fy=Math.sin(a);}}
  if(sp>25)S.set=1;
  // 突進進行中
  if(S.dash){const D=S.dash;D.t+=dt;if(D.t<=D.dur){const v=D.dist/D.dur;tryMove(P,D.ux*v*dt,D.uy*v*dt*0.8);}else S.dash=null;}
  S.chk=(S.chk||0)-dt;if(S.chk>0)return;S.chk=0.1;
  if(ckLv('k_revive')&&!(S.cd.revive>0)&&P.hp<P.maxhp*CKV.revive.hp){P.hp=Math.max(P.hp,P.maxhp*CKV.revive.to);S.cd.revive=CKV.revive.cd;pop(P.x,P.y-86,'死裡逃生','#7dff9a',1.2);spawnFx(FXMETA[744]?744:2244,P.x,P.y,true);SND.play(109,0.9,60);}
  if(ckLv('k_slayer')&&!(S.cd.slayer>0)&&!(S.slT>time)){const R=GRID*14;if(mons.some(m=>m.boss&&!m.dead&&Math.hypot(m.x-P.x,(m.y-P.y)*2)<R)){S.slT=time+CKV.slayer.dur;S.cd.slayer=CKV.slayer.cd;pop(P.x,P.y-86,'魔王殺手','#ff8a5a',1.0);}}
  // 盾牌衝擊：玩家周圍 3 格（全方向）
  {const r=ckLv('k_shield');if(r&&!(S.cd.shield>0)){const R=CKV.shield.rng[r-1]*GRID;let hit=[];
    for(const m of mons){if(m.dead)continue;if(Math.hypot(m.x-P.x,m.y-P.y)<=R+(m.boss?18:0))hit.push(m);}
    if(hit.length){S.cd.shield=CKV.shield.cd[r-1];if(window.__ck==='knight')hellFx();else spawnFx(CKFX.shield,P.x,P.y,true);for(const m of hit){const dx=m.x-P.x,dy=m.y-P.y,d=Math.hypot(dx,dy)||1;ckDmg(m,CKV.shield.mul[r-1]);if(!m.dead)ckCtl(m,dx/d,dy/d,CKV.shield.kb,0);}}}}
  // 騎士：地裂術（砸在怪最多的地方）
  {const r=ckLv('k_quake');if(r&&!(S.cd.quake>0)){const R=CKV.quake.rad*GRID,L=CKV.quake.look*GRID;let best=null,bn=0;
    const near=mons.filter(m=>!m.dead&&!m.hid&&Math.hypot(m.x-P.x,m.y-P.y)<=L);
    for(const c of near){let n=0;for(const o of near)if(Math.hypot(o.x-c.x,(o.y-c.y)*2)<=R)n++;if(n>bn){bn=n;best=c;}}
    if(best){S.cd.quake=CKV.quake.cd;const cx=best.x,cy=best.y;spawnFx(11750,cx,cy);SND.play(128,0.7,150);
      for(const m of near){if(m.dead)continue;if(Math.hypot(m.x-cx,(m.y-cy)*2)<=R+(m.boss?18:0)){ckDmg(m,CKV.quake.mul[r-1]);if(!m.dead)ckCtl(m,0,0,0,CKV.quake.root);}}}}}
  // 騎士：劍氣風暴（8 方向各一發）
  {const r=ckLv('k_storm');if(r&&!(S.cd.storm>0)&&mons.some(m=>!m.dead&&!m.hid&&Math.hypot(m.x-P.x,m.y-P.y)<=CKV.wave.rng)){S.cd.storm=CKV.storm.cd[r-1];const pierce=ckLv('k_wpier'),life=(CKV.wave.rng+formRng())/CKV.wave.spd;
    for(let i=0;i<8;i++){const a=i*Math.PI/4;arrows.push({x:P.x,y:P.y-22,vx:Math.cos(a)*CKV.wave.spd,vy:Math.sin(a)*CKV.wave.spd,a,life,pierce,hit:new Set(),mul:CKV.wave.mul,kw:1});}
    kwSnd();pop(P.x,P.y-86,'劍氣風暴','#ffd27a',0.9);}}
  // 反擊屏障：啟動期間，頭上持續顯示魔法
  if(S.cntT>time){S.cntFx=(S.cntFx||0)-0.1;if(S.cntFx<=0){S.cntFx=0.8;spawnFx(CKFX.counter,P.x,P.y-52,false);}}
  for(const m of mons){if(m.dead||!(m.stunT>0))continue;if(!(m.sfxAt>time)){m.sfxAt=time+0.5;hitFx(CKFX.stun,m.x,m.y-34,false);}}   // 暈眩期間每 0.5 秒在怪物頭上播一次特效
  // 龍之旋斬
  {const r=ckLv('l_spin');if(r&&!(S.cd.spin>0)){const R=CKV.spin.rad[r-1]*GRID*wm().range;let hit=[];
    for(const m of mons){if(m.dead)continue;if(Math.hypot(m.x-P.x,m.y-P.y)<=R+(m.boss?18:0))hit.push(m);}
    if(hit.length){S.cd.spin=CKV.spin.cd;spawnFx(CKFX.spin,P.x,P.y,true);for(const m of hit){ckDmg(m,CKV.spin.mul[r-1]);if(!m.dead)ckCtl(m,0,0,0,CKV.spin.stun);}}}}
  // 暗影突襲
  {const r=ckLv('d_dash');if(r&&!(S.cd.dash>0)&&S.moving&&!S.dash){const R=CKV.dash.look*GRID,ch=Math.cos(Math.PI/4);let n=0;
    for(const m of mons){if(m.dead)continue;const dx=m.x-P.x,dy=m.y-P.y,d=Math.hypot(dx,dy);if(d>R||d<0.01)continue;if((dx*S.fx+dy*S.fy)/d>=ch&&++n>=CKV.dash.need)break;}
    if(n>=CKV.dash.need){S.cd.dash=CKV.dash.cd;S.dash={t:0,dur:CKV.dash.dur,dist:CKV.dash.dist[r-1]*GRID,ux:S.fx,uy:S.fy,red:CKV.dash.red[r-1]};spawnFx(CKFX.dash,P.x,P.y,true);}}}
}
