  {const ck=window.__ck,dv=({royal:3,knight:2,elf:3,mage:5,darkelf:4,dk:3,ill:3})[ck]||3;d=Math.max(1,d-rndi(0,Math.floor(Math.max(0,10-P.st.ac)/dv))-P.st.dr);}   // 原版：傷害 − 隨機(0~(10−防禦)÷職業係數) − 減傷
  for(const [v,p] of P.dx.drR)if(Math.random()*100<p)d=Math.max(1,d-v);
  if(ckHoly())d=Math.max(1,d*(1-HOLY.blk));
  {const rd=ckRed();if(rd>0){d=Math.max(1,d*(1-rd));const S=ckState();if(!(S.cd.gfx>0)){S.cd.gfx=3;if(ckLv('k_guard'))spawnFx(CKFX.guard,P.x,P.y,true);if(ckLv('l_skin'))spawnFx(CKFX.skin,P.x,P.y,true);}}}   // 堅固防禦／龍之護鎧／突進減傷（加總有上限）
  if(TM.red>0)d=Math.max(1,d*(1-TM.red));   // 天賦：堅毅不拔
  if(ckLv('k_iron'))d=Math.max(1,d*(1-CKV.iron));   // 鋼鐵意志：所有怪物傷害 −25%
  if(P.ed&&P.ed.dd>0)d*=1.25;   // 邪咒：受到傷害 +25%
  if(ckSlayOn()&&((_att&&_att.boss)||(_src&&_src.indexOf('（首領）')>=0)))d=Math.max(1,d*(1-CKV.slayer.red));   // 魔王殺手：首領傷害 −45%
  lastHurtAt=time;const dIn=d;
  const ab=Math.min(P.mp,d);if(ab>0){P.mp-=ab;d-=ab;}   // 護盾：傷害先扣護盾值，扣完才扣生命
  P.hurt=0.2;   // 被打到後沒有無敵時間
  if(ab>0)pop(P.x,P.y-60-(d>0.01?14:0),'-'+Math.round(ab),'#7fb8ff',0.7);
  if(d>0.01){P.hp-=d;lastHit={n:_src||'不明的力量',d:Math.round(d)};pop(P.x,P.y-60,'-'+Math.round(d),'#ff6a6a',0.7);}
