  {const r=ckLv('k_spike');if(r&&_att&&!_att.dead&&Math.hypot(_att.x-P.x,_att.y-P.y)<120)ckHit(_att,dIn*CKV.spike[r-1]);}   // 騎士尖刺盔甲：反彈近戰傷害
