function endGame(win,home){
  hideClearWin();if(over)return;over=true;pendingLv=0;try{document.getElementById('lvl').classList.add('hidden');hideTip();}catch(e){}running=false;if(RUNON){saveSave();saveVill();CLOUD.flush();}if(!win){SND.plr('death');SND.music([120],true);}saveLoot();saveSave();saveVill();let _fr=null;try{if(RUNON&&CLOUD.reportFn)_fr=CLOUD.reportFn();}catch(e){}if(RUNON){RUNON=false;if(!EVRUN)CLOUD.runEnd(win?'win':home?'home':'dead',0,_fr);}if(EVRUN){EVRUN=false;CLOUD.runEnd(win?'win':home?'home':'dead',stageT,_fr);}
  {// 結算畫面的怪物肖像（天堂R）：通關＝本關首領；陣亡＝致命一擊的怪物；有肖像才顯示
    let pg=0,cap='';const ST=STAGES[stageIdx];
    if(win&&ST&&ST.boss&&PORTRAIT_SET.has(ST.boss.gfx)){pg=ST.boss.gfx;cap='擊敗首領：'+ST.boss.name;}
    else if(!win&&!home&&lastHit){let bd=null;for(const d of DATA.monsters){if(PORTRAIT_SET.has(d.gfx)&&lastHit.n.indexOf(d.name)>=0&&(!bd||d.name.length>bd.name.length))bd=d;}if(bd){pg=bd.gfx;cap='倒在「'+bd.name+'」手下';}}
    const bx=document.getElementById('endPic');document.getElementById('endPicImg').style.display='none';if(pg&&win){document.getElementById('endPicCap').textContent=cap;bx.style.display='block';}else bx.style.display='none';}   // 不顯示怪物肖像，只用文字說明（通關寫擊敗的首領；陣亡看「致命一擊」那行）
  document.getElementById('endTitle').textContent=home?'傳送回村莊':win?'通關！':'你倒下了';
  document.getElementById('endKill').textContent=win||!lastHit?'':'致命一擊：'+lastHit.n+'　造成 '+lastHit.d+' 點傷害';
  document.getElementById('endSub').textContent='存活 '+fmt(time)+'　擊殺 '+kills+'　等級 '+level+(win?'':'　　這場撿到的東西都保留');
  const box=document.getElementById('endLoot');box.innerHTML='';
  const names=Object.keys(sessionLoot);
  if(!names.length){box.innerHTML='<span style="color:#9d9378">這局沒有掉寶</span>';}
  for(const n of names){const e=document.createElement('em');e.innerHTML='<img src="assets/icons/'+LOOTID[n]+'.png" style="vertical-align:middle;margin-right:4px">';e.appendChild(document.createTextNode(n+(sessionLoot[n]>1?' ×'+sessionLoot[n]:'')));box.appendChild(e);}
  document.getElementById('end').classList.toggle('win',!!win);
  setTimeout(()=>document.getElementById('end').classList.remove('hidden'),win?600:900);
}
function hms(s){s=Math.max(0,Math.ceil(s));return Math.floor(s/3600)+':'+String(Math.floor(s/60)%60).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
