    for(let j=j0;j<=j1;j++)for(let i=i0;i<=i1;i++){const im=chunkAt(i,j);if(im&&im._ok&&im.naturalWidth){const sw=im._m?MCH/2:MCH;ctx.drawImage(im,0,0,sw,sw,i*MCH,j*MCH,MCH+1,MCH+1);}}
