const WORDER=['help','char','skill','inv','party','opt','sys'];
const OPT_DEF={sfxOn:!TOUCHDEV,musOn:true,sfxVol:0.7,musVol:0.5,names:true,hpbars:true,dmg:false,miss:true,lootpop:true,noCoinSnd:false,buffnote:true,noFx:false,fxMode:0,mobLite:true,perf:false,noDuel:false,gfx:(TOUCHDEV?2:0),scale:(TOUCHDEV?1.5:1),alpha:1};   // 手機預設把介面放大一點
const OPT=Object.assign({},OPT_DEF);window.OPT=OPT;
try{Object.assign(OPT,JSON.parse(localStorage.getItem('l1s_opt')||'{}'));}catch(e){}
if(OPT.noFx){if(!OPT.fxMode)OPT.fxMode=1;OPT.noFx=false;}   // 舊的「關閉命中特效」勾選 → 轉成「半關」
const FXMODE_N=['全部顯示','半關','全關'];
// ---- GM：產生手機小圖（地圖塊＋怪物圖縮成一半、存成 webp，傳到伺服器的 _m 資料夾；原圖完全不動）----
//   一整組（一個地圖資料夾／一隻怪的全部圖）都傳成功才登記，手機只用已登記的組；可中途停止，下次跳過已登記的接著做
let MRB=null;
async function mresBuild(){
  if(!(window.CLOUD&&CLOUD.gm)){addChat('只有 GM 可以使用。','warn');return;}
  if(MRB){MRB.box.style.display='block';return;}
  {const t=document.createElement('canvas');t.width=t.height=2;const b=await new Promise(r=>t.toBlob(r,'image/webp',0.8));if(!b||b.type!=='image/webp'){addChat('這個瀏覽器不能產生 webp 圖，請改用電腦的 Chrome 或 Edge。','warn');return;}}
  const box=document.createElement('div');box.style.cssText='position:fixed;right:10px;top:70px;z-index:99998;width:330px;background:#1b150d;border:2px solid #7a6036;border-radius:8px;padding:10px 12px;color:#e6dcc4;font-size:13px;line-height:1.6;box-shadow:0 6px 24px #000';
  box.innerHTML='<div style="color:#ffd27a;font-size:15px">產生手機小圖</div><div id="mrbT">準備中…</div><div id="mrbE" style="color:#ff9a8a;font-size:12px;max-height:90px;overflow:auto"></div><div style="text-align:right;margin-top:6px"><span id="mrbS" style="cursor:pointer;padding:3px 10px;border:1px solid #7a6036;border-radius:5px">停止</span> <span id="mrbH" style="cursor:pointer;padding:3px 10px;border:1px solid #4a3b22;border-radius:5px;color:#aba383">縮小</span></div>';
  ['mousedown','pointerdown','touchstart','wheel'].forEach(ev=>box.addEventListener(ev,e=>e.stopPropagation()));document.body.appendChild(box);
  const R=MRB={box,stop:false,up:0,bytes:0,orig:0,fail:0,mapDone:0,mapAll:0,gfxDone:0,gfxAll:0,cur:''};
  const T=box.querySelector('#mrbT'),E=box.querySelector('#mrbE');
  box.querySelector('#mrbS').onclick=()=>{R.stop=true;box.querySelector('#mrbS').textContent='停止中…';};
  box.querySelector('#mrbH').onclick=()=>{box.style.display='none';addChat('手機小圖在背景繼續產生，到選項→其他再按一次可以看進度。','sys');};
  const WHY={};const err=(id,e)=>{R.fail++;let m=String((e&&e.message)||e||'');const why=/讀不到/.test(m)?'伺服器上沒有原圖（遊戲本來就沒用到，可忽略）':/太大/.test(m)?'檔案太大':/413|too large/i.test(m)?'檔案太大（伺服器拒收）':/403|401|登入/.test(m)?'登入失效（重新登入後再按一次）':/轉檔/.test(m)?'轉檔失敗':'連線或伺服器錯誤（再按一次會重試）';
    WHY[why]=WHY[why]||{n:0,g:new Set()};WHY[why].n++;WHY[why].g.add(id);E.innerHTML=Object.keys(WHY).map(k=>'<div>'+k+'：'+WHY[k].n+' 張（'+WHY[k].g.size+' 組）</div>').join('');};
  const show=()=>{T.innerHTML='地圖 '+R.mapDone+' / '+R.mapAll+'　怪物 '+R.gfxDone+' / '+R.gfxAll+'<br>已傳 '+R.up+' 張（'+(R.bytes/1048576).toFixed(1)+'MB）　失敗 '+R.fail+'<br><span style="color:#aba383">'+R.cur+'</span>';};
  const tick=setInterval(show,500);
  const loadImg=src=>new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=()=>rej(new Error('讀不到 '+src));im.src=src;});
  const shrink=async(src,key,area)=>{   // 讀原圖 → 縮一半 → webp → 上傳（area＝怪物圖在資料表裡的寬高：只取這個範圍，原圖右下有留白也對得準）
    const im=await loadImg(src);
    const SW=area?area[0]:im.naturalWidth,SH=area?area[1]:im.naturalHeight;
    let b=null;
    for(const [sc,q] of (area?[[0.5,0.86],[0.5,0.7],[0.34,0.75],[0.25,0.7]]:[[0.5,0.86],[0.5,0.7],[0.5,0.55]])){   // 地圖固定縮一半（畫的時候是用一半來算），只降畫質   // 檔案超過 1.4MB（伺服器上限）就降畫質、再縮小
      const w=Math.max(1,Math.round(SW*sc)),h=Math.max(1,Math.round(SH*sc));
      const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.imageSmoothingEnabled=true;x.imageSmoothingQuality='high';x.drawImage(im,0,0,SW,SH,0,0,w,h);
      b=await new Promise(r=>c.toBlob(r,'image/webp',q));if(!b||b.type!=='image/webp')throw new Error('轉檔失敗');
      if(b.size<=1400000)break;
    }
    if(b.size>1400000)throw new Error('檔案太大');
    for(let a=0;;a++){try{await CLOUD.putRaw('/api/gm/mres?k='+encodeURIComponent(key),b,'image/webp');break;}catch(e){if(a>=2||e.status===400||e.status===403)throw e;await new Promise(r=>setTimeout(r,1500*(a+1)));}}
    R.up++;R.bytes+=b.size;
  };
  const runGroup=async(t,id,items)=>{   // 一組：全部成功才登記
    let i=0,bad=0;const W=3;
    await Promise.all(Array.from({length:W},async()=>{while(!R.stop&&i<items.length){const it=items[i++];try{await shrink(it.src,it.key,it.area);}catch(e){bad++;err(id,e);}}}));
    if(R.stop||bad)return false;
    for(let a=0;;a++){try{await CLOUD.api('POST','/api/gm/mres-done',{t,id:String(id),n:items.length});return true;}catch(e){if(a>=3){err(id,e);return false;}await new Promise(r=>setTimeout(r,2000*(a+1)));}}
  };
  try{
    const have=await CLOUD.api('GET','/api/mres');const hm=new Set((have.map||[]).map(String)),hg=new Set((have.gfx||[]).map(String));
    // 地圖：所有已載入的地圖資訊，依資料夾去重
    const dirs={};const addInfo=q=>{if(q&&q.dir&&q.files&&q.files.length){const n=mapDirName(q.dir);if(/^[A-Za-z0-9_]{1,40}$/.test(n)&&!dirs[n])dirs[n]=q;}};
    if(window.MAPS)for(const k in MAPS)addInfo(MAPS[k]&&MAPS[k].info);if(typeof MAPINFO!=='undefined')addInfo(MAPINFO);
    const maps=Object.keys(dirs).filter(n=>!hm.has(n));R.mapAll=maps.length;
    const gfx=Object.keys(META).filter(g=>/^\d{1,6}$/.test(g)&&!hg.has(g));
    const gsz=g=>{let v=0;for(const f in META[g]){const m=META[g][f];v+=m.cols*m.cellW*(m.rows||Math.ceil(m.frames/m.cols))*m.cellH;}return v;};
    gfx.sort((a,b)=>gsz(b)-gsz(a));R.gfxAll=gfx.length;   // 最佔記憶體的怪先做（像龍、大型首領），效果最明顯
    for(const n of maps){if(R.stop)break;const q=dirs[n];R.cur='地圖 '+n+'（'+q.files.length+' 塊）';await new Promise(r=>setTimeout(r,0));
      const base=q.dir.replace(/\/+$/,'')+'/',pre=/^\.\.\/maps\//.test(base)?'maps/':/^assets\//.test(base)?'v163/assets/':null;
      if(!pre){err(n,new Error('地圖位置不支援'));R.mapDone++;continue;}
      const items=q.files.filter(f=>/^\d{1,3}_\d{1,3}\.webp$/.test(f)).map(f=>({src:base+f,key:pre+n+'_m/'+f}));
      try{if(await runGroup('map',n,items))R.mapDone++;}catch(e){err(n,e);}}
    for(const g of gfx){if(R.stop)break;const fs=Object.keys(META[g]);R.cur='怪物／角色圖 '+g+'（'+fs.length+' 張）';
      const items=fs.filter(f=>/^\d{1,4}$/.test(f)).map(f=>{const m=META[g][f];return {src:'assets/'+g+'/'+g+'-'+f+'.png',key:'v163/assets/'+g+'_m/'+g+'-'+f+'.webp',area:[m.cols*m.cellW,(m.rows||Math.ceil(m.frames/m.cols))*m.cellH]};});
      if(!items.length){R.gfxDone++;continue;}
      try{if(await runGroup('gfx',g,items))R.gfxDone++;}catch(e){err(g,e);}}
    mresFetch();
    R.cur=R.stop?'已停止（下次按會從沒做完的接著做）':R.fail?('做完了，但有 '+R.fail+' 張失敗：那幾組沒有登記，手機照用原圖（再按一次會重試）。'):'全部完成！手機玩家重新整理後就會用小圖。';
  }catch(e){R.cur='中斷：'+(e.message||e);}
  R.fin=true;clearInterval(tick);show();box.querySelector('#mrbS').textContent='關閉';box.querySelector('#mrbS').onclick=()=>{box.remove();MRB=null;};
  addChat('手機小圖：'+R.cur+'（地圖 '+R.mapDone+'/'+R.mapAll+'、怪物 '+R.gfxDone+'/'+R.gfxAll+'，失敗 '+R.fail+'）','sys');
}
