function clanMenu(n){
  if(!mkOn())return;CLN=n;
  srvDo('clanInfo',{},r=>{
    CLANNAMES.clear();if(r.mine)for(const x of r.mine.members)CLANNAMES.add(x.name);
    const rows=[];
    if(r.mine){
      const m=r.mine,lead=!!r.iAmLeader;
      for(const x of m.members)rows.push({name:(x.leader?'★ ':'')+x.name,info:(CLSN[x.cls]||x.cls)+'　Lv'+x.lv+(x.leader?'　盟主':''),fn:(lead&&!x.leader)?()=>clanMember(x.name):null});
      rows.push({name:lead?'解散血盟':'退出血盟',info:'',fn:()=>clanSure(lead?'解散':'退出',lead?'clanDisband':'clanLeave',lead?'血盟解散後，所有盟友都會被移出，無法復原。':'退出後可以再加入別的血盟，或自己創立。')});
      listWin({id:'clan',title:'血盟：'+m.name,rows,total:'盟友 '+m.members.length+' / '+r.max+' 人',hint:lead?'點盟友可轉讓盟主／移出':''});
    }else{
      rows.push({name:'【創立血盟】',info:'花費 '+r.cost.toLocaleString()+' 金幣',fn:()=>clanMakeForm(r.cost)});
      for(const c of r.list)rows.push({name:c.name,info:'盟主 '+(c.leader||'?')+'　'+c.n+' / '+r.max+' 人',fn:()=>c.n>=r.max?addChat('這個血盟人數已滿。','warn'):clanSure('加入「'+c.name+'」','clanJoin','加入後就是這個血盟的盟友。',{id:c.id})});
      listWin({id:'clan',title:'血盟',rows,total:'你還沒有加入血盟',hint:'點血盟可加入'});
    }
  });
}
