const MOUSE={x:0,y:0,held:false};
function mouseWorld(){const vw=W/ZOOM,vh=H/ZOOM;return {x:MOUSE.x/ZOOM+P.x-vw/2,y:MOUSE.y/ZOOM+P.y-vh/2};}
const TALK_CURSOR='url(assets/cursor/talk.png) 4 4, pointer';   // 原版「嘴巴」游標圖放在 assets/cursor/talk.png；沒有這張圖時退回手指游標
function npcAt(w){let b=null,bd=48*48;for(const n of VNPC){if(n.kind==='guard')continue;const p=npcXY(n),d=(p.x-w.x)**2+(p.y-20-w.y)**2;if(d<bd){bd=d;b=n;}}return b;}
let _nhT=0,_nhM=null;
function nameHover(m){   // 普通怪平常不顯示名字，滑鼠移過去（最靠近的那隻）才顯示
  const t=performance.now();if(t-_nhT>30){_nhT=t;_nhM=(P&&running&&!village)?monAt(mouseWorld()):null;}
  return _nhM===m;
}
function remoteAt(w){let b=null,bd=34*34;for(const r of NET.R.values()){const d=(r.x-w.x)**2+(r.y-30-w.y)**2;if(d<bd){bd=d;b=r;}}return b;}

// GM：在遊戲裡點玩家 → 看素質／裝備，或禁言、踢出（只有 GM 帳號；伺服器會再驗證一次）
function gmCall(op,body){
  const api=String(window.L1S_API||'').replace(/\/$/,'');
  return fetch(api+'/admin/gm/'+op,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+(window.CLOUD&&CLOUD.token||'')},body:JSON.stringify(body||{})}).then(r=>r.json()).catch(()=>({ok:false,error:'連不上伺服器'}));
}
function gmPlayerAct(k,name){
  if(k==='m'){const h=prompt('禁言「'+name+'」幾小時？（0＝永久）','1');if(h===null)return;const hh=Math.max(0,parseInt(h,10)||0);gmCall('mute',{name,hours:hh,reason:'GM 在遊戲內禁言'}).then(j=>addChat(j.ok?'已禁言 '+name+(hh?'（'+hh+' 小時）':'（永久）'):'禁言失敗：'+(j.error||''),j.ok?'sys':'warn'));return;}
  if(k==='u'){gmCall('unmute',{name}).then(j=>addChat(j.ok?'已解除 '+name+' 的禁言':'解除失敗：'+(j.error||''),j.ok?'sys':'warn'));return;}
  if(k==='b'){if(!confirm('確定要把「'+name+'」踢下線嗎？（對方可以馬上重新登入）'))return;gmCall('kick',{name}).then(j=>addChat(j.ok?'已踢出 '+name:'踢出失敗：'+(j.error||''),j.ok?'sys':'warn'));return;}
  if(k==='g')gmPlayerView(name);
}
function gmPlayerView(name){
  let o=document.getElementById('gmPv');
  if(!o){o=document.createElement('div');o.id='gmPv';o.style.cssText='position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);z-index:99999;width:min(94vw,460px);max-height:84vh;overflow:auto;background:#101216f2;border:2px solid #ffb0b0;border-radius:8px;padding:10px;color:#fff;font:13px/1.6 sans-serif';document.body.appendChild(o);}
  o.style.display='block';o.textContent='讀取中…';
  gmCall('char',{name}).then(j=>{
    if(!j.ok){o.textContent='讀取失敗：'+(j.error||'');const x=document.createElement('div');x.textContent='關閉';x.style.cssText='margin-top:8px;padding:5px;background:#333;border-radius:4px;text-align:center;cursor:pointer';x.onclick=()=>o.style.display='none';o.appendChild(x);return;}
    const esc=t=>String(t==null?'':t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
    const S=j.stats||{};const sn=[['str','力量'],['dex','敏捷'],['con','體質'],['int','智力'],['wis','精神'],['cha','魅力']].filter(x=>S[x[0]]!=null).map(x=>x[1]+' '+S[x[0]]).join('　');
    const eq=(j.inv||[]).filter(i=>i.eq);const bag=(j.inv||[]).filter(i=>!i.eq);
    const li=a=>a.length?a.map(i=>esc(i.nm)+(i.ench?' +'+i.ench:'')+(i.n>1?' ×'+i.n:'')).join('、'):'（無）';
    o.innerHTML='<div style="font-size:16px;color:#ffd75e;margin-bottom:4px">'+esc(j.name)+'　<span style="font-size:12px;color:#ccc">帳號 '+esc(j.user)+'</span></div>'
     +'<div>職業：'+esc((typeof CLSN!=='undefined'&&CLSN[j.cls])||j.cls)+'　等級：'+(j.lv|0)+'　金幣：'+(j.gold|0).toLocaleString()+'</div>'
     +'<div>'+(sn?'能力：'+esc(sn):'')+'</div>'
     +'<div>位置：'+esc(j.where||'離線')+(j.ban?'　<b style="color:#f66">封鎖中</b>':'')+'</div>'
     +'<div style="margin-top:6px;color:#9fdcff">身上裝備</div><div>'+li(eq)+'</div>'
     +'<div style="margin-top:6px;color:#9fdcff">背包（'+bag.length+' 種）</div><div style="max-height:110px;overflow:auto">'+li(bag)+'</div>'
     +'<div style="margin-top:10px;display:flex;gap:6px;flex-wrap:wrap"><span class="gb" data-a="m">禁言</span><span class="gb" data-a="u">解除禁言</span><span class="gb" data-a="b">踢出</span><span class="gb" data-a="c">關閉</span></div>';
    o.querySelectorAll('.gb').forEach(b=>{b.style.cssText='padding:5px 12px;background:#5a2a2a;border-radius:4px;cursor:pointer';b.onclick=()=>{const a=b.dataset.a;if(a==='c'){o.style.display='none';return;}gmPlayerAct(a,name);};});
  });
}
function openPlayerMenu(r,x,y){
  let m=$id('pmenu');if(!m){m=document.createElement('div');m.id='pmenu';document.body.appendChild(m);document.addEventListener('mousedown',ev=>{if(!ev.target.closest||!ev.target.closest('#pmenu'))m.style.display='none';});}
  const GMM=!!(window.CLOUD&&CLOUD.gm&&ONLINE);
  m.innerHTML='<div class="pt"></div><div class="po" data-k="w">密語</div>'+(GMM?'<div class="po" data-k="g">GM：查看玩家</div><div class="po" data-k="m">GM：禁言</div><div class="po" data-k="u">GM：解除禁言</div><div class="po" data-k="b">GM：踢出</div>':'')+'<div class="po" data-k="x">取消</div>';
  m.firstChild.textContent=r.n;m.style.display='block';m.style.left=Math.min(x,innerWidth-130)+'px';m.style.top=Math.min(y,innerHeight-(GMM?190:110))+'px';
  m.onmousedown=e=>e.stopPropagation();
  m.onclick=e=>{const k=e.target.dataset&&e.target.dataset.k;if(!k)return;if(k==='t')return;m.style.display='none';if(k==='w'){const i=window.__chatIn;if(i){i.value='/w '+r.n+' ';i.focus();}}else if(GMM&&'gmub'.includes(k))gmPlayerAct(k,r.n);};
}
