// ---- 離線版：同一套規則在本機算（點數＝永久等級−1＋首領首殺；存在這台瀏覽器） ----
function talLocalCalc(){const n=TALST.n=TALST.n||{};let used=0;for(const k of Object.keys(n)){const d=TALN[k];if(!d){delete n[k];continue;}n[k]=Math.max(0,Math.min(d.max,Math.floor(+n[k])||0));if(!n[k]){delete n[k];continue;}used+=n[k]*d.cost;}
  TALST.fk=Array.isArray(TALST.fk)?TALST.fk:[];if(used>(Math.max(0,((PL.S?PL.S().lv:1)||1)-1)+TALST.fk.length+Math.max(0,Math.floor(+TALST.bx)||0))){TALST.n={};used=0;}TALST.used=used;TALST.bx=Math.max(0,Math.floor(+TALST.bx)||0);TALST.total=Math.max(0,((PL.S?PL.S().lv:1)||1)-1)+TALST.fk.length+TALST.bx;}
function talLocalSave(){try{localStorage.setItem(ckey('l1s_tal'),JSON.stringify({n:TALST.n,fk:TALST.fk,bx:TALST.bx||0}));}catch(e){}}
function talLocalLoad(){try{const o=JSON.parse(localStorage.getItem(ckey('l1s_tal'))||'null')||{};TALST={n:o.n||{},fk:o.fk||[],bx:o.bx||0,total:0,used:0};}catch(e){TALST={n:{},fk:[],bx:0,total:0,used:0};}talLocalCalc();}
function talOp(op,a,ok){   // 連線版問伺服器；離線版本機算（規則跟 worker/src/talent.js 一樣）
  if(false && SRV()){srvDo(op,a,r=>{TALST=r.tal;talApply();ok();});return;}
  talLocalLoad();
  try{
    if(op==='talUp'){const d=TALN[a.id];if(!d)throw new Error('沒有這個天賦');const l=TALST.n[a.id]||0;if(l>=d.max)throw new Error('已經滿級了');
      if(talBrSpent(d.br)<(d.tier-1)*TAL_GATE)throw new Error('這條路線要先投入更多點數才能解鎖這一層');if(talLeft()<d.cost)throw new Error('天賦點不夠');TALST.n[a.id]=l+1;}
    else if(op==='talDown'){const e=talDownErr(a.id);if(e)throw new Error(e);if(countItem(49100)<TAL_DOWN_COIN)throw new Error('回收需要 '+TAL_DOWN_COIN+' 個倖存者金幣');takeItem(49100,TAL_DOWN_COIN);const l=TALST.n[a.id]-1;if(l>0)TALST.n[a.id]=l;else delete TALST.n[a.id];saveSave();}
    else if(op==='talReset'){const rc=TALST.used*TAL_RESET_COIN;if(rc<=0)throw new Error('目前沒有投入任何天賦點');if(countItem(49100)<rc)throw new Error('洗點需要 '+rc+' 個倖存者金幣');takeItem(49100,rc);TALST.n={};saveSave();}
    talLocalCalc();talLocalSave();talApply();ok();
  }catch(e){addChat(e.message||'操作失敗','warn');}
}

