let TALSEL='s1',TALRST=false,TALHELPON=false,TALBRSEL=null;
const TALS={s5:'每場免死一次',a5:'所有傷害再 +8%',g5:'升級多 1 張選項',t7:'六項素質各 +2',t8:'六項素質各 +3',c2:'技能冷卻 −10%',g4:'每場重抽 +1 次'};
function talShort(id){if(TALS[id])return TALS[id];const d=TALN[id];return d.d(1).replace(/^(.*?)\s*([+−-]\s*\d+%?)$/,'$1 $2')+'／級';}
function talDownErr(id){const d=TALN[id];if(!d)return '沒有這個天賦';const l=TALST.n[id]||0;if(l<=0)return '這個天賦還沒學';const n2=Object.assign({},TALST.n);n2[id]=l-1;if(!n2[id])delete n2[id];
  for(const k in n2){const e=TALN[k];let o=0;for(const j in n2)if(j!==k&&TALN[j].br===e.br)o+=n2[j]*TALN[j].cost;if(o<(e.tier-1)*TAL_GATE)return '不能回收：後面的天賦靠這一級才解鎖，請先回收更上層的';}return '';}
function talRefund(id){TALSEL=id;TALBRSEL=null;TALRST=false;const e=talDownErr(id);if(e){addChat(e,'warn');talRender();return;}
  if(countItem(49100)<TAL_DOWN_COIN){addChat('回收需要 '+TAL_DOWN_COIN+' 個倖存者金幣。','warn');talRender();return;}
  talOp('talDown',{id},()=>{addChat('已回收一級天賦，退回點數。','sys');talRender();});}
function talState(id){const d=TALN[id],l=TALST.n[id]||0,need=(d.tier-1)*TAL_GATE,sp=talBrSpent(d.br);return {d,l,need,sp,lock:sp<need,full:l>=d.max,buy:sp>=need&&l<d.max&&talLeft()>=d.cost};}
function talOpenTree(n){
  npcOpen=true;{const a=$id('lw');if(a)a.classList.add('hidden');const dd=$id('npcdlg');if(dd)dd.classList.add('hidden');const nw=$id('npcwin');if(nw)nw.classList.add('hidden');}
  let w=$id('talw');
  if(!w){w=document.createElement('div');w.id='talw';document.body.appendChild(w);
    const fit=()=>{const sc=Math.min(1,innerHeight*.97/900,innerWidth*.98/1200);w.style.setProperty('--tws',sc.toFixed(3));};fit();addEventListener('resize',fit);addEventListener('orientationchange',fit);}
  w._n=n;w.classList.add('on');TALRST=false;TALHELPON=false;TALBRSEL=null;talRender();
}
function talRender(){
  const w=$id('talw');if(!w)return;
  const left=talLeft();
  let h='<div class="bg"></div><img class="bgi" src="assets/ui3/tal_bg.png" onerror="this.style.display=\'none\'"><img class="frm" src="assets/ui3/tal_frame.png" onload="this.parentNode.classList.add(\'hasf\')" onerror="this.style.display=\'none\'"><svg viewBox="0 0 1200 760"><defs><filter id="tmist" x="-20%" y="-20%" width="140%" height="140%"><feGaussianBlur stdDeviation="2.2"/></filter></defs>';
  const pt=id=>id==='T'?[600,640]:TALPOS[id];
  for(const [a,b] of TALEDGE){const A=pt(a),B=pt(b),d=TALN[b],lit=(TALST.n[b]||0)>0;
    const mx=(A[0]+B[0])/2+(B[0]<A[0]?-30:30)*(a==='T'?1.4:0.5),my=(A[1]+B[1])/2;
    h+='<path class="tp'+(lit?' lit':'')+'" d="M'+A[0]+' '+A[1]+' Q'+mx+' '+my+' '+B[0]+' '+B[1]+'" style="color:'+TALCOL[d.br]+(lit?';stroke:'+TALCOL[d.br]:'')+'"/>';}
  h+='</svg>';
  for(const br of ['S','A','G','C','T']){const pos={S:[300,150],A:[900,100],G:[700,66],C:[540,718],T:[30,722]}[br];
    h+='<div class="tr'+(TALBRSEL===br?' sel':'')+'" data-br="'+br+'" style="left:'+pos[0]+'px;top:'+pos[1]+'px;color:'+TALCOL[br]+'">'+TALBR[br][0]+'　'+talBrSpent(br)+' 點</div>';}
  for(const id of Object.keys(TALN)){const t=talState(id),p=TALPOS[id],col=TALCOL[t.d.br];
    h+='<div class="tn'+(t.l>0?' on':'')+(t.lock?' lock':'')+(t.buy?' buy':'')+(t.full?' max':'')+(TALSEL===id&&!TALBRSEL?' sel':'')+'" data-id="'+id+'" style="left:'+p[0]+'px;top:'+p[1]+'px;color:'+col+';">'+
      '<img src="assets/ui3/tal_'+id+'.png" onerror="this.onerror=function(){this.replaceWith(Object.assign(document.createElement(\'span\'),{className:\'ch\',textContent:\''+talName(id).slice(0,2)+'\'}))};this.src=\'assets/ui3/tal_'+t.d.br+'.png\'">'+
      '<div class="nm">'+talName(id)+'</div><div class="lv">'+t.l+'/'+t.d.max+'</div><div class="ef">'+talShort(id)+'</div></div>';}
  h+='<div class="top"><span>剩餘天賦點 <b>'+left+'</b></span><span style="font-size:15px;color:#cdbf9a">永久等級 '+Math.max(0,(PL.S?PL.S().lv:1)-1)+' ＋ 首領首殺 '+(TALST.fk||[]).length+(TALST.bx?' ＋ 測試 '+TALST.bx:'')+'</span><span style="flex:1"></span>'+
    '<span class="btn" id="talHelpB">玩法說明</span><span class="btn'+(TALST.used>0?'':' off')+'" id="talRstB">'+(TALRST?'再按一次確認洗點（'+TALST.used*TAL_RESET_COIN+' 倖存幣）':'洗點')+'</span>'+(!SRV()?'<span class="btn" id="talBxB">【離線測試】+10 點</span>':'')+'<span class="btn" id="talXB">離開</span></div>';
  h+='<div class="hp'+(TALHELPON?' on':'')+'" id="talHelp">'+TALHELP.replace(/</g,'&lt;')+'</div>';
  let info='',act='';
  if(TALBRSEL){info='<b style="color:'+TALCOL[TALBRSEL]+'">'+TALBR[TALBRSEL][0]+'路線</b>　已投入 '+talBrSpent(TALBRSEL)+' 點\n'+TALROUTE[TALBRSEL].replace(/^【[^】]*】/,'').replace(/</g,'&lt;');}
  else{const t=talState(TALSEL),d=t.d,nx=d.d(Math.min(d.max,t.l+1)),cur=t.l>0?d.d(t.l):'（尚未學習）';
    info='<b style="color:'+TALCOL[d.br]+'">'+talName(TALSEL)+'</b>　'+TALBR[d.br][0]+'路線・第 '+d.tier+' 層　Lv.'+t.l+'/'+d.max+'　每級 '+d.cost+' 點\n'+
      TALH[TALSEL].replace(/</g,'&lt;')+'\n<span style="color:#9fe0a0">目前：'+cur+'</span>　'+(t.full?'<span style="color:#ffd75e">已滿級</span>':'<span style="color:#ffd75e">下一級：'+nx+'</span>');
    act=t.full?'<div class="btn off">已滿級</div>':t.lock?'<div class="btn off">未解鎖</div><div style="font-size:14px;color:#e8a">本路線要先投入 '+t.need+' 點（目前 '+t.sp+'）</div>':t.buy?'<div class="btn" id="talBuyB">學習／升級（'+d.cost+' 點）</div>':'<div class="btn off">天賦點不夠</div><div style="font-size:14px;color:#e8a">還差 '+(d.cost-left)+' 點</div>';
    if(t.l>0)act+='<div class="btn" id="talDnB" style="margin-top:6px">回收一級（'+TAL_DOWN_COIN+' 倖存幣）</div>';
    act+='<div style="font-size:13px;color:#b9a77a;margin-top:4px">左鍵升級　右鍵回收</div>';}
  h+='<div class="info"><div class="tx">'+info+'</div><div class="ac">'+act+'</div></div>';
  w.innerHTML=h;
  w.querySelectorAll('.tn').forEach(e=>{
    e.onclick=()=>{const id=e.dataset.id;TALSEL=id;TALBRSEL=null;TALHELPON=false;TALRST=false;if(talState(id).buy)talOp('talUp',{id},()=>talRender());else talRender();};   // 左鍵：能學就直接升一級
    e.oncontextmenu=ev=>{ev.preventDefault();talRefund(e.dataset.id);};});
  w.querySelectorAll('.tr').forEach(e=>e.onclick=()=>{TALBRSEL=e.dataset.br;TALHELPON=false;TALRST=false;talRender();});
  const q=i=>$id(i);
  if(q('talBuyB'))q('talBuyB').onclick=()=>talOp('talUp',{id:TALSEL},()=>talRender());
  if(q('talDnB'))q('talDnB').onclick=()=>talRefund(TALSEL);
  q('talHelpB').onclick=()=>{TALHELPON=!TALHELPON;talRender();};
  q('talXB').onclick=npcClose;
  if(q('talBxB'))q('talBxB').onclick=()=>{TALST.bx=(TALST.bx||0)+10;talLocalCalc();talLocalSave();talRender();};
  q('talRstB').onclick=()=>{if(!(TALST.used>0))return;if(!TALRST){TALRST=true;talRender();return;}TALRST=false;
    if(countItem(49100)<TALST.used*TAL_RESET_COIN){addChat('洗點需要 '+TALST.used*TAL_RESET_COIN+' 個倖存者金幣（每投入 1 點 1 個）。','warn');talRender();return;}
    talOp('talReset',{},()=>{addChat('天賦已洗點，點數全部退還。','sys');talRender();});};
}
// ---- 舊的清單式天賦畫面（保留備用，不再使用） ----
function talLeft(){return (TALST.total||0)-(TALST.used||0);}
function talBrSpent(br){let c=0;for(const k in TALST.n)if(TALN[k]&&TALN[k].br===br)c+=TALST.n[k]*TALN[k].cost;return c;}
function talMain(n){
  talLocalLoad();talApply();talOpenTree(n);return;
}
function talMenu(n){
  const rows=['S','A','G','C'].map(br=>({icon:49100,name:TALBR[br][0]+'　已投入 '+talBrSpent(br)+' 點',info:TALBR[br][1],fn:()=>talBranch(n,br)}));
  rows.push({icon:49100,name:'洗點（花 '+TALST.used*TAL_RESET_COIN+' 個倖存者金幣）',info:'全部天賦點退還，重新分配',off:!(TALST.used>0),fn:()=>{if(countItem(49100)<TALST.used*TAL_RESET_COIN){addChat('洗點需要 '+TALST.used*TAL_RESET_COIN+' 個倖存者金幣（每投入 1 點 1 個）。','warn');return;}talOp('talReset',{},()=>{addChat('天賦已洗點，點數全部退還。','sys');talMenu(n);});}});
  if(!SRV())rows.push({icon:49100,name:'【離線測試】送我 10 點天賦點',info:'只有離線版有；連線版的點數由伺服器發',fn:()=>{TALST.bx=(TALST.bx||0)+10;talLocalCalc();talLocalSave();talMenu(n);}});
  listWin({id:'talm',title:n.name+'：天賦樹',rows,total:'剩餘天賦點 '+talLeft(),hint:'（等級 '+Math.max(0,(PL.S?PL.S().lv:1)-1)+'＋首殺 '+(TALST.fk||[]).length+'）'});
}
function talBranch(n,br){
  const ids=Object.keys(TALN).filter(k=>TALN[k].br===br).sort((a,b)=>TALN[a].tier-TALN[b].tier);
  const sp=talBrSpent(br);
  const rows=[{icon:49100,name:'← 返回',info:'回到路線選單',fn:()=>talMenu(n)}];
  for(const id of ids){const d=TALN[id],l=TALST.n[id]||0,need=(d.tier-1)*TAL_GATE,lock=sp<need,full=l>=d.max,short=talLeft()<d.cost;
    rows.push({icon:49100,name:'第'+d.tier+'層　'+talName(id)+'　Lv.'+l+'/'+d.max,info:full?'已滿級　'+d.d(l):lock?'需要本路線先投入 '+need+' 點（目前 '+sp+'）':'→ '+d.d(l+1)+'　花 '+d.cost+' 點',tip:d.d(Math.max(1,l)),
      off:full||lock||short,fn:()=>{talOp('talUp',{id},()=>talBranch(n,br));}});}
  listWin({id:'talb'+br,title:n.name+'：'+TALBR[br][0],rows,total:'剩餘天賦點 '+talLeft(),hint:'本路線已投入 '+sp+' 點'});
}
function dailyList(n){
  if(!SRV()){addChat('每日任務只在連線版提供。','sys');npcClose();return;}
  srvDo('dqGet',{},r=>dailyShow(n,r.dq));
}
