    if(b.t<0)continue;
    if(b.k==='f'){const k=b.t/0.5,r=20+k*70;ctx.globalCompositeOperation='lighter';const gr=ctx.createRadialGradient(b.x,b.y,2,b.x,b.y,r);gr.addColorStop(0,'rgba('+b.c+','+(0.85*(1-k))+')');gr.addColorStop(1,'rgba('+b.c+',0)');ctx.fillStyle=gr;ctx.beginPath();ctx.arc(b.x,b.y,r,0,6.283);ctx.fill();ctx.globalCompositeOperation='source-over';continue;}
    ctx.fillStyle='rgba(0,0,0,0.28)';ctx.beginPath();ctx.ellipse(b.x,b.y,9*(1-Math.min(0.5,b.z/160)),4,0,0,6.283);ctx.fill();   // 地上的影子
    const im=iconImg(b.id);if(im&&im.complete&&im.naturalWidth)ctx.drawImage(im,Math.round(b.x-im.naturalWidth/2),Math.round(b.y-b.z-im.naturalHeight/2-8));
    if(b.rest>0&&b.rest<0.9){const nm=(ITEMS[b.id]?ITEMS[b.id].name:'')+(b.n>1?' ×'+b.n.toLocaleString():'');ctx.font='bold 11px "Microsoft JhengHei","Noto Sans TC",sans-serif';ctx.textAlign='center';ctx.lineWidth=3;ctx.strokeStyle='#000';ctx.strokeText(nm,b.x,b.y-30);ctx.fillStyle='#ffe9a8';ctx.fillText(nm,b.x,b.y-30);}
