function boxRoll(kind){
  const pool=BOXPOOL[kind];let t=0;for(const a of pool)t+=a[1];let r=Math.random()*t,id=pool[0][0];
  for(const a of pool){r-=a[1];if(r<=0){id=a[0];break;}}
  const e=Math.random(),ench=e<0.01?3:e<0.05?2:e<0.2?1:0;
  const it=addItem(id,1);if(it)it.ench=ench;return {id,ench};
}
function gacha(n,kind){
  const nm=kind==='weapon'?'隨機武器包':'隨機裝備包';
  const draw=c=>{const cost=c===10?BOXCOST10:BOXCOST;if(false && SRV()){srvDo('gacha',{kind,count:c},r=>{boxLast[kind]=r.got;for(const g of r.got)addChat('開出 '+(g.ench?'+'+g.ench+' ':'')+ITEMS[g.id].name,'loot');gacha(n,kind);});return;}
    if(gold()<cost){addChat('金幣不足。','sys');return;}
    let used=0;for(const i of inv)if(i.id!==40308)used++;
    if(BAGN-used<c){addChat('背包空間不足，抽 '+c+' 次需要至少 '+c+' 格空位。','warn');return;}
    takeItem(40308,cost);const got=[];for(let i=0;i<c;i++)got.push(boxRoll(kind));boxLast[kind]=got;
    for(const g of got)addChat('開出 '+(g.ench?'+'+g.ench+' ':'')+ITEMS[g.id].name,'loot');invDirty=true;saveSave();gacha(n,kind);};
  const rows=[{name:'開 1 個'+nm,info:BOXCOST+' 金幣',off:gold()<BOXCOST,fn:()=>draw(1)},
              {name:'開 10 個'+nm,info:BOXCOST10+' 金幣',off:gold()<BOXCOST10,fn:()=>draw(10)}];
  if(boxLast[kind].length){rows.push({name:'── 剛才開出的東西 ──',off:1});
    for(const g of boxLast[kind])rows.push({icon:g.id,name:(g.ench?'+'+g.ench+' ':'')+ITEMS[g.id].name,info:g.ench>=2?'稀有！':'',off:1});}
  listWin({id:'box'+kind,title:n.name+'：'+nm,rows,total:goldTxt(),hint:'可能附帶強化'});
}
