const DOLLBY={};for(const d of DOLLS)DOLLBY[d.id]=d;
let dollSel='';
if(dollSel&&!DOLLBY[dollSel])dollSel='';
// 輔助魔法（Doll_Add_Skill）：沿用本遊戲對應魔法的加成
const DADD={26:{dex:5},42:{str:5},48:{dmg:2,hit:2},151:{ac:-5},148:{dmg:4},149:{bowHit:6},168:{ac:-7},163:{dmg:6},166:{bowDmg:3},79:{mpr:4},68:{dr:3}};
function dollStats(st){
  const X={expMul:1,spd:1,eva:0,dmgR:[],drR:[],skills:[],hpTR:0,mpTR:0};P.dx=X;
  const d=P.doll;if(!d)return;
  for(const [c,v,p] of d.pw){
    switch(c){
    case 'Doll_Ac':st.ac+=v;break;case 'Doll_Hp':st.hp+=v;break;case 'Doll_Mp':st.mp+=v;break;
    case 'Doll_HpTR':X.hpTR+=v/p;break;case 'Doll_MpTR':X.mpTR+=v/p;break;
    case 'Doll_HpR':st.hpr+=v;break;case 'Doll_MpR':st.mpr+=v;break;
    case 'Doll_Dmg':st.dmg+=v;break;case 'Doll_Hit':st.hit+=v;break;
    case 'Doll_DmgBow':st.bowDmg+=v;break;case 'Doll_HitBow':st.bowHit+=v;break;
    case 'Doll_DmgR':X.dmgR.push([v,p]);break;
    case 'Doll_DmgDown':st.dr+=v;break;case 'Doll_DmgDownR':X.drR.push([v,p]);break;case 'Doll_DmgDown_Npc':X.drR.push([v,5]);break;
    case 'Doll_Exp':X.expMul+=v/100;break;
    case 'Doll_Sp':st.sp+=v;break;case 'Doll_Mr':st.mr+=v;break;
    case 'Doll_Evasion':X.eva+=v;break;case 'Doll_Speed':X.spd=1.33;break;
    case 'Doll_Stat_Str':st.str+=v;break;case 'Doll_Stat_Dex':st.dex+=v;break;case 'Doll_Stat_Con':st.con+=v;break;
    case 'Doll_Stat_Int':st.int+=v;break;case 'Doll_Stat_Wis':st.wis+=v;break;case 'Doll_Stat_Cha':st.cha+=v;break;
    case 'Doll_Skill':X.skills.push([v,p]);break;
    case 'Doll_Add_Skill':{const a=DADD[v];if(a)for(const k in a)st[k]=(st[k]||0)+a[k];break;}
    }
  }
}
function setDoll(id){
  const d=id?DOLLBY[id]:null;P.doll=d||null;
  if(!d){P.dollE=null;recalc();return;}
  for(const g in DOLLMETA){if(!META[g])META[g]={};for(const f in DOLLMETA[g])if(!META[g][f])META[g][f]=DOLLMETA[g][f];}
  for(const g of [d.gfx,d.shadow])if(g&&DOLLMETA[g])for(const f in DOLLMETA[g]){const k=key(g,f);if(!imgs[k]){imgs[k]=sprLoad(new Image(),g,f);}}
  P.dollE={x:P.x-32,y:P.y+6,dir:P.dir,moving:false};
  recalc();P.hp=P.maxhp;P.mp=P.maxmp;
}
function updateDoll(dt){
  const E=P.dollE;if(!E)return;
  const tx=P.x-34,ty=P.y+8,dx=tx-E.x,dy=ty-E.y,dist=Math.hypot(dx,dy);
  if(dist>320){E.x=P.x-20;E.y=P.y+6;E.moving=false;}
  else if(dist>10){const sp=Math.min(dist*4,P.speed*1.25+20)*dt,k=Math.min(1,sp/dist);E.x+=dx*k;E.y+=dy*k;E.dir=dirFromVec(dx,dy);E.moving=true;}
  else E.moving=false;
}
function drawDoll(){
  const d=P.doll,E=P.dollE;if(!d||!E||P.hp<=0)return;
  drawAct(d.gfx,d.shadow,d.walk,E.moving?performance.now():0,true,E.dir,E.x,E.y);
}
