     +'#mchat{position:fixed;left:8px;right:8px;top:calc(env(safe-area-inset-top,0px) + 8px);z-index:99991;display:none;flex-wrap:wrap;gap:6px;align-items:center;background:rgba(20,14,6,.94);border:1px solid #b79a55;border-radius:10px;padding:8px}'
     +'#mchat input{flex:1 1 60px;width:60px;min-width:0;height:34px;box-sizing:border-box;font-size:16px;padding:0 8px;border:1px solid #8a7440;border-radius:6px;background:#1a1409;color:#fff;outline:none}'
     +'#mchat .chs{flex:1 1 100%;display:none;gap:6px}#mchat .chs.show{display:flex}#mchat .chs div{flex:1 1 0;padding:6px 0;font-size:14px;opacity:.55;border-color:#6b5a30}#mchat .chs div.on{opacity:1;border-color:#f1e3b8;background:rgba(120,88,24,.98)}#mchat .mto{flex:1 1 100%;display:none}'
     +'#mchat div{flex:0 0 auto;padding:7px 11px;border-radius:6px;background:rgba(80,56,16,.95);border:1px solid #b79a55;color:#f1e3b8;font:bold 14px "Microsoft JhengHei",sans-serif;text-align:center}';
