// ---- 系統更新提醒：定時偵測伺服器上的版本，有新版就跳出提示請玩家重新整理 ----
(function(){
  const mp=h=>{const o={};for(const m of (h.match(/<script[^>]+src="[^"]*"/g)||[])){const u=(m.match(/src="([^"]*)"/)||[])[1]||'';if(u.indexOf('?v=')<0)continue;o[u.split('?')[0]]=u.split('?v=')[1];}return o;};
  let cur=null;try{cur=mp([...document.querySelectorAll('script[src]')].map(e=>'<script src="'+e.getAttribute('src')+'">').join(''));}catch(e){}
  if(!cur||!Object.keys(cur).length)return;
  const differs=h=>{const n=mp(h);if(!Object.keys(n).length)return false;for(const k in cur){if(n[k]!==undefined&&n[k]!==cur[k])return true;}return false;};
  let shown=false;
  function show(){
    if(shown)return;shown=true;
    const b=document.createElement('div');b.id='updBar';
    b.style.cssText='position:fixed;left:50%;top:10px;transform:translateX(-50%);z-index:99990;max-width:92vw;box-sizing:border-box;padding:10px 14px;border-radius:10px;background:rgba(40,28,8,.97);border:2px solid #ffd75e;color:#fff3c0;font:700 15px "Microsoft JhengHei","Noto Sans TC",sans-serif;display:flex;gap:10px;align-items:center;box-shadow:0 4px 18px rgba(0,0,0,.6)';
    const t=document.createElement('div');t.style.cssText='line-height:1.4';t.innerHTML='🔔 遊戲已更新！<span id="updMsg">這局打完回到村莊後，會自動重新整理載入新版。</span><br><span style="font-size:12px;color:#d8c58a">想現在就更新，可以按右邊按鈕（會中斷目前的戰局）。</span>';
    const go=document.createElement('div');go.textContent='重新整理';go.style.cssText='flex:0 0 auto;padding:8px 12px;border-radius:8px;background:rgba(150,110,20,.95);border:1px solid #ffd75e;cursor:pointer;touch-action:manipulation';
    go.onclick=()=>{try{location.reload();}catch(e){}};
    const x=document.createElement('div');x.textContent='✕';x.style.cssText='flex:0 0 auto;padding:4px 8px;cursor:pointer;color:#d8c58a';x.onclick=()=>{b.remove();};
    b.appendChild(t);b.appendChild(go);b.appendChild(x);document.body.appendChild(b);
    try{addChat('系統已更新！這局打完回到村莊後會自動重新整理載入新版。','sys');}catch(e){}
    forceWatch();
  }
  // 強制更新：已偵測到新版，只要人在村莊（戰局打完回村）就倒數 5 秒自動重新整理；戰局中不打斷
  function doReload(){try{if(typeof PL!=='undefined'&&PL.flushSave)PL.flushSave();}catch(e){}try{saveSave();}catch(e){}try{sessionStorage.setItem('l1s_autoreload',String(Date.now()));}catch(e){}location.reload();}
  function forceWatch(){
    let last=0;try{last=+sessionStorage.getItem('l1s_autoreload')||0;}catch(e){}
    if(Date.now()-last<90000)return;   // 剛自動重新整理過卻還是偵測到新版（例如網路快取）：不要無限重新整理，改成只提醒
    let t0=0,iv=setInterval(()=>{
      let ok=false;try{ok=!!village&&!npcOpen&&!!P;}catch(e){}
      const msg=document.getElementById('updMsg');
      if(DUEL){t0=0;if(msg)msg.textContent='決鬥中：打完回到村莊後才會自動重新整理。';return;}
      if(MRB&&!MRB.fin){t0=0;if(msg)msg.textContent='GM 正在產生手機小圖：做完後才會自動重新整理（中途按停止也會）。';return;}   // 不要打斷 GM 產生小圖
      if(!ok){t0=0;if(msg)msg.textContent='這局打完回到村莊後，會自動重新整理載入新版。';return;}
      if(!t0)t0=Date.now();   // 用實際時間算倒數（視窗在背景時計時器會變慢，不能靠次數）
      const left=5-Math.floor((Date.now()-t0)/1000);
      if(msg)msg.textContent='已回到村莊，'+Math.max(left,0)+' 秒後自動重新整理載入新版…';
      if(left<=0){clearInterval(iv);doReload();}
    },1000);
  }
  async function chk(){
    if(shown)return;   // 視窗被蓋住或在背景也照樣檢查（以前被蓋住會跳過，導致提示不出來）
    try{const r=await fetch(location.pathname+'?_u='+Date.now(),{cache:'no-store'});if(!r.ok)return;const h=await r.text();if(differs(h))show();}catch(e){}
  }
  // 村莊閒置踢線：在村莊 60 分鐘沒有「介面操作」（開NPC對話、賭狗、點背包裝備天賦、打字；單純走路或點地圖不算） → 存檔、登出、回到登入畫面（戰局中不踢），把名額讓給排隊的人
  (function(){
    let lastAct=Date.now(),kicking=false;const IDLE_MS=3600000;
    const bump=()=>{lastAct=Date.now();};
    window.__idleBump=bump;   // 開 NPC 視窗、伺服器操作（賭狗、買賣、強化…）時呼叫
    // 只有「點到遊戲畫布以外的介面」（背包、裝備、天賦、NPC 視窗…）或在輸入框打字才算有動作；走來走去、點地圖、滑鼠移動、滾輪都不算（防連點器／按鍵精靈掛網）
    ['mousedown','touchstart'].forEach(ev=>window.addEventListener(ev,e=>{const t=e.target;if(t&&t.id!=='c')bump();},{capture:true,passive:true}));
    window.addEventListener('keydown',e=>{const t=e.target;if(t&&(t.tagName==='INPUT'||t.tagName==='TEXTAREA'))bump();},{capture:true,passive:true});
    setInterval(()=>{
      let inV=false;try{inV=!!village&&!!P;}catch(e){}
      if(!inV){lastAct=Date.now();return;}   // 不在村莊（戰局中）不計閒置；回到村莊從頭算 60 分鐘
      try{if(window.CLOUD&&CLOUD.gm){lastAct=Date.now();return;}}catch(e){}   // GM 帳號永遠不踢
      if(kicking||Date.now()-lastAct<IDLE_MS)return;
      kicking=true;
      (async()=>{
        try{if(typeof PL!=='undefined'&&PL.flushSave)PL.flushSave();}catch(e){}try{saveSave();}catch(e){}
        try{sessionStorage.setItem('l1s_idlekick','1');}catch(e){}
        try{if(window.CLOUD&&CLOUD.mode==='server')await CLOUD.logout();}catch(e){}
        location.reload();
      })();
    },5000);
  })();
  setInterval(chk,150000);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)setTimeout(chk,1500);});
  setTimeout(chk,60000);
  window.__updChk=chk;
})();
