// ================= 雙人決鬥（PVP）客戶端 ／ 2026-11-14 =================
// 伺服器（worker duel.js）當裁判：抽卡、升級、冷卻、命中、扣血、怪物、補血球、毒圈、勝負都以伺服器為準
// 這裡只負責：送出移動／選卡／瞬間移動／目標設定，以及把伺服器送來的狀態畫出來
let DUEL=null,DREG=false;   // DREG：自己有沒有登記決鬥
const DU_CAT={atk:['攻擊','#ff8a4a'],sup:['輔助','#6fdc9a']};
function duelInvite(who){if(duelOff()){addChat('雙人決鬥暫時關閉。','warn');return;}
  if(!(typeof ONLINE!=='undefined'&&ONLINE&&window.CLOUD&&CLOUD.char)){addChat('決鬥只有連線版才能使用。','warn');return;}
  if(!village||!NET.ok){addChat('要在村莊裡才能邀請決鬥（雙方都要在村莊）。','warn');return;}
  if(DUEL){addChat('你正在決鬥中。','warn');return;}
  netSend({t:'dinv',to:who});
}
function duelMsg(m){
  switch(m.t){
    case 'dinfo':addChat(m.m,m.w?'warn':'sys');break;
    case 'dlist':DREG=!!m.me;duelListWin(m.a||[]);break;
    case 'dreg':DREG=!!m.on;break;
    case 'dinv':duelInvitePopup(m.from,m.c);break;
    case 'dstart':duelStart(m);break;
    case 'ds':if(DUEL)duelState(m);break;
    case 'de':if(DUEL)for(const e of m.e)duelEvent(e);break;
    case 'doffer':if(DUEL)duelOffer(m.cards,m.pend);break;
    case 'dsk':if(DUEL){DUEL.sk={};for(const [k,lv,d] of m.sk)DUEL.sk[k]={lv,d};DUEL.hudSk=true;}break;
    case 'dfix':if(DUEL){P.x=m.x;P.y=m.y;DUEL.dash=null;}break;
    case 'ddash':if(DUEL)DUEL.dash={dx:m.dx,dy:m.dy,t:0,dur:0.18,ox:P.x,oy:P.y};break;
    case 'dblinkok':if(DUEL)DUEL.blinkCd=m.cd;break;
    case 'dend':if(DUEL)duelEnd(m);break;
  }
}
