  duelHudBuild();
  if(!$id('duelCss')){const st=document.createElement('style');st.id='duelCss';st.textContent='body.induel #hud{background:none!important}body.induel #hud>*:not(#chat):not(#chatBar):not(#annStrip){visibility:hidden!important}';document.head.appendChild(st);}
  document.body.classList.add('induel');try{if(MM.wrap)MM.wrap.style.display='none';}catch(e){}
