  if(mx||my){const l=Math.hypot(mx,my);mx/=l;my/=l;P.x+=mx*140*hs*dt;P.y+=my*140*hs*dt*0.8;P.dir=dirFromVec(mx,my);P.moving=true;}else P.moving=false;
  {const dx=P.x-D.A.cx,dy=P.y-D.A.cy,d=Math.hypot(dx,dy),lim=D.A.r*1.25;if(d>lim){P.x=D.A.cx+dx/d*lim;P.y=D.A.cy+dy/d*lim;}}
